-- 116: Help redesigned with the Owner (2026-11-06): guides by activity, each person sees only what they can do.
--
-- Generated by Documentazione/guide-help/build.mjs. Replaces the 18 old pages, which described the old paths
-- ("Promote", + New document for everyone), with 27 guides in English and Italian. The old pages, with any edit
-- made to them in the app, stay in _backup_help_pages_20261106 (Supabase dashboard only).
-- Urdu can be added later as language 'ur', with the Owner's words. Read aloud is not yet shown to plain Users:
-- when it is announced, run:  update help_pages set audience = audience || 'user' where guide_key = 'read-aloud';
--
-- Run this BEFORE merging the PR. Running it twice is harmless on the day; once Admins edit guides in the app, a
-- rerun would overwrite those edits. The old Help screen keeps working in the meantime, listing the new guides.

begin;

create table if not exists public._backup_help_pages_20261106 as table public.help_pages;
alter table public._backup_help_pages_20261106 enable row level security;

alter table public.help_pages add column if not exists guide_key text;
alter table public.help_pages add column if not exists summary text;
alter table public.help_pages add column if not exists section text;
alter table public.help_pages add column if not exists audience text[] not null default '{}';

alter table public.help_pages drop constraint if exists help_pages_language_check;
alter table public.help_pages add constraint help_pages_language_check check (language in ('it', 'en', 'ur'));

delete from public.help_pages;

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, updated_at, updated_by_email)
values ('find-read_en', 'find-read', 'en', null, 'Find and read', 'Search, filters, listen, watch, save', 'use', array['user'], $help_guide$<p class="lead">Every document in the archive can be found from one screen. It is called <b>Library</b> for Users and <b>Dashboard</b> for everyone on the team.</p>
<h2>Find a document</h2>
<ol>
<li><b>Type in the search box.</b> It looks in titles, tags and the Urdu text itself.</li>
<li><b>Or type a number</b> in <b>ID #</b>, if you know it.</li>
<li><b>Narrow the list</b> with <b>Filters</b>: Category, Author, Main topic, Recipient, Source, Collection, Language. Several filters work together.</li>
<li><b>Press a row</b> to open the document.</li>
</ol>
<p><b>Language</b> starts on Urdu for Users and Operators. If you find nothing, check that filter first. <b>Clear all filters and search</b> starts again.</p>
<h2>What you can do with a document</h2>
<ul>
<li><b>Open PDF</b>: opens the file. <b>Download</b> appears instead for a PDF that hasn't reached Drive yet.</li>
<li><b>Read (large print)</b>: the text alone, in large letters.</li>
<li><b>Open editable text</b>: shows the text so you can copy it. It doesn't change the archive.</li>
<li><b>Listen</b> and <b>Watch video</b>: appear when the document has a reading or a video.</li>
<li><b>☆ Save</b>: keeps it in <b>My Space</b>, private to you.</li>
<li><b>Report a problem</b>: tells the team, with the document number already filled in.</li>
</ul>
<details><summary>Other languages and versions</summary>
<p>A text and its translations, audio and video belong together. You find them under <b>Other versions of this document</b>: press one to open it. The star marks the version shown first for that language and format.</p>
</details>
<details><summary>Only audio and video</summary>
<p>The <b>Audio and video only</b> button shows just readings and videos. Rows with a reading or a video also carry a mark. This helps those who cannot search by typing.</p>
</details>
<details><summary>The Word of Life of the month</summary>
<p>In <b>Start Here</b>, a card opens this month's Word of Life with one tap, with <b>Listen</b> and <b>Watch video</b> when they exist. A Word of Life is dated by its own month, not by the magazine that printed it.</p>
</details>
<details><summary>Why can't I find a document?</summary>
<ul>
<li>A filter may still be on, often <b>Language</b>.</li>
<li>A document with only a PDF can be found by title and tags, not by its text.</li>
<li>Some documents are reserved: for those who aren't enabled, they don't appear at all.</li>
</ul>
</details>
<p><a class="btn" href="#" data-tab="dashboard">Open the archive</a></p>$help_guide$, 10, now(), 'migration 116');

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, updated_at, updated_by_email)
values ('find-read_it', 'find-read', 'it', null, 'Trovare e leggere', 'Ricerca, filtri, ascolto, video, salvataggio', 'use', array['user'], $help_guide$<p class="lead">Ogni documento dell'archivio si trova da una sola schermata. Si chiama <b>Library</b> per gli User e <b>Dashboard</b> per chi fa parte del team.</p>
<h2>Trovare un documento</h2>
<ol>
<li><b>Scrivi nella casella di ricerca.</b> Cerca nei titoli, nei tag e nel testo urdu.</li>
<li><b>Oppure scrivi un numero</b> in <b>ID #</b>, se lo conosci.</li>
<li><b>Restringi l'elenco</b> con <b>Filters</b>: Category, Author, Main topic, Recipient, Source, Collection, Language. Più filtri lavorano insieme.</li>
<li><b>Premi una riga</b> per aprire il documento.</li>
</ol>
<p><b>Language</b> parte su Urdu per User e Operatori. Se non trovi nulla, controlla prima questo filtro. <b>Clear all filters and search</b> ricomincia da capo.</p>
<h2>Che cosa puoi fare con un documento</h2>
<ul>
<li><b>Open PDF</b>: apre il file. Al suo posto compare <b>Download</b> per un PDF non ancora arrivato su Drive.</li>
<li><b>Read (large print)</b>: solo il testo, a caratteri grandi.</li>
<li><b>Open editable text</b>: mostra il testo per copiarlo. Non cambia l'archivio.</li>
<li><b>Listen</b> e <b>Watch video</b>: compaiono quando il documento ha una lettura o un video.</li>
<li><b>☆ Save</b>: lo conserva in <b>My Space</b>, privato per te.</li>
<li><b>Report a problem</b>: avvisa il team, con il numero del documento già compilato.</li>
</ul>
<details><summary>Altre lingue e versioni</summary>
<p>Un testo con le sue traduzioni, l'audio e il video stanno insieme. Li trovi sotto <b>Other versions of this document</b>: premine uno per aprirlo. La stella indica la versione mostrata per prima per quella lingua e quel formato.</p>
</details>
<details><summary>Solo audio e video</summary>
<p>Il pulsante <b>Audio and video only</b> mostra solo letture e video. Anche le righe con una lettura o un video portano un segno. Questo aiuta chi non può cercare scrivendo.</p>
</details>
<details><summary>La Parola di Vita del mese</summary>
<p>In <b>Start Here</b>, una scheda apre con un tocco la Parola di Vita del mese, con <b>Listen</b> e <b>Watch video</b> quando esistono. Una Parola di Vita è datata col suo mese, non con la rivista che l'ha stampata.</p>
</details>
<details><summary>Perché non trovo un documento?</summary>
<ul>
<li>Può essere rimasto attivo un filtro, spesso <b>Language</b>.</li>
<li>Un documento con il solo PDF si trova per titolo e tag, non per il testo.</li>
<li>Alcuni documenti sono riservati: per chi non è abilitato non compaiono affatto.</li>
</ul>
</details>
<p><a class="btn" href="#" data-tab="dashboard">Apri l'archivio</a></p>$help_guide$, 10, now(), 'migration 116');

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, updated_at, updated_by_email)
values ('boards_en', 'boards', 'en', null, 'Boards', 'Read and post in your group', 'use', array['user'], $help_guide$<p class="lead">A board is a shared space for a group: reflections, texts, links, images. <b>What is posted on a board is not in the archive.</b> It doesn't appear in searches or reports.</p>
<h2>Read</h2>
<p>Open <b>Boards</b> and choose a group from the buttons at the top. You can read every board. The app notes by itself that you have seen a post: nothing to press.</p>
<h2>Post</h2>
<ol>
<li>Choose the board and press <b>+ New post</b>.</li>
<li>The first time, read the rules and press <b>I understand, continue</b>.</li>
<li>Write your text. You can add a link or an image.</li>
<li>Publish. If you are a User, an editor of that board reads it first. An Operator's post appears at once.</li>
</ol>
<details><summary>The rules of a board</summary>
<ul>
<li>A board is for what serves the formation and spiritual life of that group.</li>
<li>It isn't for advertising, political campaigning, chain messages or anything off-topic.</li>
<li>An editor can reject or remove a post and must give the reason.</li>
<li>Repeated misuse can lower an Operator's reputation, or block a User from posting. An editor proposes this, and a Formation or HR lead decides: never one person alone.</li>
</ul>
</details>
<details><summary>A post that deserves the archive</summary>
<p>Press <b>Suggest for the archive</b> on the post. The suggestion reaches the board's editors, Archive &amp; Data and the Coordinators, who can propose it through the normal review or decline it.</p>
</details>
<details><summary>Who has read a post</summary>
<p>Everyone sees how many have read a post. Only the board's editors, Coordinators and Admins can see who.</p>
</details>
<p><a class="btn" href="#" data-tab="boards">Open Boards</a></p>$help_guide$, 20, now(), 'migration 116');

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, updated_at, updated_by_email)
values ('boards_it', 'boards', 'it', null, 'Bacheche', 'Leggere e pubblicare nel tuo gruppo', 'use', array['user'], $help_guide$<p class="lead">Una bacheca è uno spazio condiviso di un gruppo: riflessioni, testi, link, immagini. <b>Ciò che si pubblica in bacheca non è nell'archivio.</b> Non compare nelle ricerche né nei report.</p>
<h2>Leggere</h2>
<p>Apri <b>Boards</b> e scegli un gruppo dai pulsanti in alto. Puoi leggere tutte le bacheche. L'app segna da sola che hai visto un post: non c'è nulla da premere.</p>
<h2>Pubblicare</h2>
<ol>
<li>Scegli la bacheca e premi <b>+ New post</b>.</li>
<li>La prima volta, leggi le regole e premi <b>I understand, continue</b>.</li>
<li>Scrivi il testo. Puoi aggiungere un link o un'immagine.</li>
<li>Pubblica. Se sei uno User, lo legge prima chi cura quella bacheca. Il post di un Operatore compare subito.</li>
</ol>
<details><summary>Le regole di una bacheca</summary>
<ul>
<li>Una bacheca serve alla formazione e alla vita spirituale di quel gruppo.</li>
<li>Non è per pubblicità, campagne politiche, catene di messaggi o cose fuori tema.</li>
<li>Chi la cura può rifiutare o togliere un post e deve dire il motivo.</li>
<li>Un abuso ripetuto può abbassare la reputazione di un Operatore o bloccare le pubblicazioni di uno User. Lo propone chi cura la bacheca e lo decide il responsabile di Formazione o di HR: mai una persona sola.</li>
</ul>
</details>
<details><summary>Un post che meriterebbe l'archivio</summary>
<p>Premi <b>Suggest for the archive</b> sul post. Il suggerimento arriva a chi cura la bacheca, ad Archive &amp; Data e ai Coordinatori, che possono proporlo con la revisione normale o declinarlo.</p>
</details>
<details><summary>Chi ha letto un post</summary>
<p>Tutti vedono quante persone hanno letto un post. Solo chi cura la bacheca, i Coordinatori e gli Admin possono vedere chi.</p>
</details>
<p><a class="btn" href="#" data-tab="boards">Apri Boards</a></p>$help_guide$, 20, now(), 'migration 116');

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, updated_at, updated_by_email)
values ('formation-paths_en', 'formation-paths', 'en', null, 'Formation Paths', 'Enroll, quizzes, certificate', 'use', array['user'], $help_guide$<p class="lead">A formation path is a course: modules and chapters to follow in order, with quizzes and a certificate at the end.</p>
<h2>Follow a path</h2>
<ol>
<li>Open <b>Formation Paths</b> and look through the <b>Catalog</b>.</li>
<li>Open a path. You can read its content even before enrolling.</li>
<li>Press <b>Enroll</b>. This opens the <b>Discussion</b> with the other participants, the quizzes and the certificate.</li>
<li>Press <b>Take quiz</b> at the end of a module. You see your result at once, and <b>Retake</b> lets you try again.</li>
<li>When you have passed what the path requires, the certificate appears by itself.</li>
</ol>
<p>You find your certificates in <b>My Profile → My Certificates</b>. They stay there even if the path is later closed.</p>
<details><summary>Leaving a path, and deadlines</summary>
<p><b>Withdraw</b> takes you out of a path at any time. A path may have an enrollment deadline: after it, the page says that enrollment is closed.</p>
</details>
<p><a class="btn" href="#" data-tab="formation">Open Formation Paths</a></p>$help_guide$, 30, now(), 'migration 116');

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, updated_at, updated_by_email)
values ('formation-paths_it', 'formation-paths', 'it', null, 'Percorsi formativi', 'Iscrizione, quiz, certificato', 'use', array['user'], $help_guide$<p class="lead">Un percorso formativo è un corso: moduli e capitoli da seguire in ordine, con quiz e un certificato alla fine.</p>
<h2>Seguire un percorso</h2>
<ol>
<li>Apri <b>Formation Paths</b> e guarda il <b>Catalog</b>.</li>
<li>Apri un percorso. Puoi leggerne il contenuto anche prima di iscriverti.</li>
<li>Premi <b>Enroll</b>. Si aprono la <b>Discussion</b> con gli altri partecipanti, i quiz e il certificato.</li>
<li>Premi <b>Take quiz</b> alla fine di un modulo. Vedi subito il risultato, e <b>Retake</b> ti fa riprovare.</li>
<li>Quando hai superato ciò che il percorso richiede, il certificato compare da solo.</li>
</ol>
<p>Trovi i certificati in <b>My Profile → My Certificates</b>. Restano lì anche se il percorso viene poi chiuso.</p>
<details><summary>Lasciare un percorso, e le scadenze</summary>
<p><b>Withdraw</b> ti toglie da un percorso in qualsiasi momento. Un percorso può avere una scadenza per le iscrizioni: dopo, la pagina dice che sono chiuse.</p>
</details>
<p><a class="btn" href="#" data-tab="formation">Apri Formation Paths</a></p>$help_guide$, 30, now(), 'migration 116');

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, updated_at, updated_by_email)
values ('propose_en', 'propose', 'en', null, 'Propose content', 'Text, PDF, audio, video: one door', 'add', array['operator'], $help_guide$<p class="lead">Proposals is the only door for adding content to the archive: you fill in a form, someone else checks it, and only their approval publishes the text. Nobody publishes alone.</p>
<p>Until it is approved, the text doesn't appear in the Library. Proposing earns no credits by itself: if you would like a compensation, agree with the team first, and they will create a task.</p>
<table><tr><th>What you want to do</th><th>Where to start</th></tr>
<tr><td>Add a new text</td><td><b>Proposals → + New proposal</b>, or <b>+ Propose content</b> on the Dashboard</td></tr>
<tr><td>Add a translation or another version of a text already there</td><td>Open the text and press <b>+ Add a related version</b></td></tr>
<tr><td>Prepare the month's Word of Life</td><td><b>Proposals → Word of Life</b></td></tr>
<tr><td>Bring a board post into the archive</td><td>On the post, <b>Propose for archive</b></td></tr></table>
<h2>The steps</h2>
<ol>
<li><b>Open the form.</b> Press <b>+ New proposal</b>.</li>
<li><b>Check whether the text already exists.</b> In part 1, search by title or by a phrase of the text. If you find the same text in another language, press <b>Link to this</b>: empty fields fill in by themselves. If it isn't there, go on: it will be a new text.</li>
<li><b>Fill in what the versions share.</b> Part 2 needs the <b>English title, category, author</b> and <b>date or period</b>. For a Word of Life, use its own month, such as <code>2026-12</code>, not the magazine's. The rest is optional.</li>
<li><b>Fill in the version.</b> In part 3, choose the <b>language</b> and the <b>title in that language</b>, then the access level and format.</li>
<li><b>Add the text.</b> Paste it, or use <b>Or load the text from Word</b>, and <b>always check it</b>. The text is what makes the document findable: a PDF alone can be found only by its title and tags.</li>
<li><b>Add the PDF, if there is one.</b> Either the text or the PDF is enough, but both are better.</li>
<li><b>Other languages?</b> Press <b>+ Another language</b> for each one. All the versions in a form are published together.</li>
<li><b>Send.</b> Press <b>Send for review</b>. If you haven't finished, press <b>Save draft</b> and come back from <b>My proposals</b>.</li>
</ol>
<div class="note"><b>Access level:</b> <b>Public</b> and <b>Private</b> suit almost everything. If you aren't sure, leave <b>Private</b>, which means visible to registered users. <b>Reserved</b> appears only for Admin and Formation.</div>
<details><summary>After sending: up to publication</summary>
<p>A Revisor or Coordinator decides, never on their own proposal, and their approval publishes every version in the form at once. <b>My proposals</b> always shows where yours stands.</p>
<table><tr><th>State</th><th>Meaning</th><th>What you can do</th></tr>
<tr><td><b>Draft</b></td><td>Yours alone</td><td><b>Edit</b> or <b>Discard</b></td></tr>
<tr><td><b>Awaiting review</b></td><td>In the queue, for so many days</td><td><b>Take back to edit</b>, as long as nobody is working on it. <b>Send a reminder</b> after 3 days, then every 3 days</td></tr>
<tr><td><b>To correct</b></td><td>The reviewer asks for a change: the note is written there</td><td><b>Edit</b>, correct, and <b>Send for review</b> again</td></tr>
<tr><td><b>Published</b></td><td>It is in the archive</td><td>Nothing</td></tr>
<tr><td><b>Rejected</b></td><td>Not accepted: the reason is written there</td><td>If needed, talk to the team</td></tr></table>
<p>The document is visible at once on publication, and the PDF opens with <b>Download</b>. An Admin then copies it to Drive, and from then on it opens with <b>Open PDF</b>. There is nothing you need to do.</p>
</details>
<details><summary>Linking texts, languages and versions</summary>
<p>Related texts means the same work: the original, its translations, the audio and the video. A person always decides the link, never the system.</p>
<ul>
<li><b>All together:</b> in the same form, with <b>+ Another language</b>.</li>
<li><b>A text already there, starting from it:</b> <b>+ Add a related version</b>. This is the safest way: the form fills in by itself and the link can't be removed.</li>
<li><b>A text already there, starting from the form:</b> in part 1, search and press <b>Link to this</b>. Here <b>Remove the link</b> undoes it.</li>
<li><b>The Word of Life:</b> in <b>Proposals → Word of Life</b>, choose the month. You see Italian, English, Urdu, video and audio with their state. Add a piece with <b>+ Add</b>, or all at once with <b>Propose everything missing together</b>.</li>
</ul>
<p>Link only versions of the same text. A commentary, or a text that is merely similar, is a work of its own. If two published documents are the same text, ask a Coordinator to join them.</p>
<p>A <b>new version in the same language</b>, such as a revised Urdu, follows the same ways. On publication it takes the star for that language and format, and the old one can still be consulted.</p>
</details>
<details><summary>Translations</summary>
<p><b>With no compensation, through a proposal:</b></p>
<ol>
<li>Open the original.</li>
<li>If you need help, press <b>Translate</b> and then <b>Copy prompt + text</b>, paste into Claude and treat what you get as a draft. Someone who knows Urdu well must always reread it.</li>
<li>When it is ready, press <b>+ Add a related version</b> on the original.</li>
<li>Check the language, write the title in that language, add the text and press <b>Send for review</b>.</li>
</ol>
<p><b>With a compensation, through a task:</b> a Coordinator creates a translation task on the original, someone with the translator qualification takes it, and it follows <a href="#" data-help-guide="tasks">the path of a task</a>.</p>
<p>Don't use both routes for the same text.</p>
</details>
<details><summary>File formats</summary>
<table><tr><th>What</th><th>Accepted</th><th>Limit</th><th>Good to know</th></tr>
<tr><td>Text</td><td>Pasted, or Word <code>.docx</code></td><td>Word up to 20 MB</td><td>Only the text is kept: layout and images are lost. Text boxes or notes may not come through, so compare it with the original</td></tr>
<tr><td>PDF</td><td><code>.pdf</code></td><td>50 MB</td><td>Alone, it can't be found by searching the text</td></tr>
<tr><td>Audio</td><td>MP3, M4A, AAC, OGG, WEBM</td><td>25 MB</td><td>MP3 and M4A are the safest. WAV is refused. The reader's name is needed under <b>Read by</b></td></tr>
<tr><td>Video</td><td>An <code>https</code> link to YouTube or Google Drive</td><td>No file uploaded</td><td>Keep the original on Drive</td></tr></table>
<p>Old Word <code>.doc</code>: save it as <code>.docx</code> first. Images: save them in a PDF. InPage <code>.inp</code>: convert it first, as below.</p>
</details>
<details><summary>Converting an InPage file</summary>
<p>Urdu texts in InPage must become Unicode before entering the archive. The file stays on your computer: the conversion happens in the browser.</p>
<ol>
<li>Open <b>InPage Converter</b> and choose the <code>.inp</code> file.</li>
<li>If you wish, fill in <b>Document ID</b> and <b>English reference</b>: they appear at the top of the Word file and the PDF.</li>
<li>Press <b>Convert</b>. The text appears in the box.</li>
<li><b>Reread it and correct it there.</b> The conversion is automatic, so it can contain mistakes.</li>
<li>The simplest way: copy the text and paste it into <b>Text</b> in the form. Or press <b>Download Word (.docx)</b> and load it with <b>Or load the text from Word</b>, or <b>Generate PDF (print)</b> and choose <b>Save as PDF</b>.</li>
</ol>
<p>Word and PDF use the Jameel Noori Nastaleeq font: install it on your computer. The <b>Google Drive folder</b> field is optional: it uploads the files to Drive, overwriting files with the same name.</p>
</details>
<p><a class="btn" href="#" data-tab="proposals">Open Proposals</a></p>$help_guide$, 40, now(), 'migration 116');

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, updated_at, updated_by_email)
values ('propose_it', 'propose', 'it', null, 'Proporre contenuti', 'Testo, PDF, audio, video: una sola porta', 'add', array['operator'], $help_guide$<p class="lead">Proposals è l'unica porta per aggiungere contenuti all'archivio: compili una scheda, qualcun altro la controlla, e solo la sua approvazione pubblica il testo. Nessuno pubblica da solo.</p>
<p>Finché non è approvato, il testo non compare nella Library. Proporre non dà crediti di per sé: se desideri un compenso, accordati prima con il team, che creerà un task.</p>
<table><tr><th>Che cosa vuoi fare</th><th>Da dove partire</th></tr>
<tr><td>Aggiungere un testo nuovo</td><td><b>Proposals → + New proposal</b>, oppure <b>+ Propose content</b> sulla Dashboard</td></tr>
<tr><td>Aggiungere una traduzione o un'altra versione di un testo già presente</td><td>Apri il testo e premi <b>+ Add a related version</b></td></tr>
<tr><td>Preparare la Parola di Vita del mese</td><td><b>Proposals → Word of Life</b></td></tr>
<tr><td>Portare in archivio un post di una bacheca</td><td>Sul post, <b>Propose for archive</b></td></tr></table>
<h2>I passi</h2>
<ol>
<li><b>Apri la scheda.</b> Premi <b>+ New proposal</b>.</li>
<li><b>Controlla se il testo esiste già.</b> Nella parte 1, cerca per titolo o per una frase del testo. Se trovi lo stesso testo in un'altra lingua, premi <b>Link to this</b>: i campi vuoti si compilano da soli. Se non c'è, prosegui: sarà un testo nuovo.</li>
<li><b>Compila ciò che le versioni hanno in comune.</b> La parte 2 chiede <b>titolo inglese, categoria, autore</b> e <b>data o periodo</b>. Per una Parola di Vita usa il suo mese, per esempio <code>2026-12</code>, non quello della rivista. Il resto è facoltativo.</li>
<li><b>Compila la versione.</b> Nella parte 3, scegli la <b>lingua</b> e il <b>titolo in quella lingua</b>, poi il livello di accesso e il formato.</li>
<li><b>Aggiungi il testo.</b> Incollalo, oppure usa <b>Or load the text from Word</b>, e <b>controllalo sempre</b>. È il testo a far trovare il documento: un PDF da solo si trova solo per titolo e tag.</li>
<li><b>Aggiungi il PDF, se c'è.</b> Basta il testo o il PDF, ma entrambi sono meglio.</li>
<li><b>Altre lingue?</b> Premi <b>+ Another language</b> per ciascuna. Tutte le versioni di una scheda vengono pubblicate insieme.</li>
<li><b>Invia.</b> Premi <b>Send for review</b>. Se non hai finito, premi <b>Save draft</b> e torna da <b>My proposals</b>.</li>
</ol>
<div class="note"><b>Livello di accesso:</b> <b>Public</b> e <b>Private</b> vanno bene quasi sempre. Se non sei sicuro, lascia <b>Private</b>, cioè visibile agli utenti registrati. <b>Reserved</b> compare solo ad Admin e Formazione.</div>
<details><summary>Dopo l'invio: fino alla pubblicazione</summary>
<p>Decide un Revisore o un Coordinatore, mai sulla propria proposta, e la sua approvazione pubblica insieme tutte le versioni della scheda. <b>My proposals</b> mostra sempre a che punto è la tua.</p>
<table><tr><th>Stato</th><th>Significato</th><th>Che cosa puoi fare</th></tr>
<tr><td><b>Draft</b></td><td>Solo tua</td><td><b>Edit</b> o <b>Discard</b></td></tr>
<tr><td><b>Awaiting review</b></td><td>In coda, da tot giorni</td><td><b>Take back to edit</b>, se nessuno ci sta lavorando. <b>Send a reminder</b> dopo 3 giorni, poi ogni 3 giorni</td></tr>
<tr><td><b>To correct</b></td><td>Il revisore chiede una modifica: la nota è scritta lì</td><td><b>Edit</b>, correggi e di nuovo <b>Send for review</b></td></tr>
<tr><td><b>Published</b></td><td>È in archivio</td><td>Nulla</td></tr>
<tr><td><b>Rejected</b></td><td>Non accettata: il motivo è scritto lì</td><td>Se serve, parla con il team</td></tr></table>
<p>Alla pubblicazione il documento si vede subito, e il PDF si apre con <b>Download</b>. Un Admin lo copia poi su Drive, e da lì in poi si apre con <b>Open PDF</b>. Tu non devi fare nulla.</p>
</details>
<details><summary>Collegare testi, lingue e versioni</summary>
<p>Testi collegati significa la stessa opera: l'originale, le traduzioni, l'audio e il video. Il collegamento lo decide sempre una persona, mai il sistema.</p>
<ul>
<li><b>Tutto insieme:</b> nella stessa scheda, con <b>+ Another language</b>.</li>
<li><b>Un testo già presente, partendo da lui:</b> <b>+ Add a related version</b>. È il modo più sicuro: la scheda si compila da sola e il collegamento non si può togliere.</li>
<li><b>Un testo già presente, partendo dalla scheda:</b> nella parte 1, cerca e premi <b>Link to this</b>. Qui <b>Remove the link</b> lo annulla.</li>
<li><b>La Parola di Vita:</b> in <b>Proposals → Word of Life</b>, scegli il mese. Vedi italiano, inglese, urdu, video e audio con il loro stato. Aggiungi un pezzo con <b>+ Add</b>, oppure tutto insieme con <b>Propose everything missing together</b>.</li>
</ul>
<p>Collega solo versioni dello stesso testo. Un commento, o un testo soltanto simile, è un'opera a sé. Se due documenti pubblicati sono lo stesso testo, chiedi a un Coordinatore di unirli.</p>
<p>Una <b>nuova versione nella stessa lingua</b>, come un urdu rivisto, segue le stesse vie. Alla pubblicazione prende la stella per quella lingua e quel formato, e la vecchia resta consultabile.</p>
</details>
<details><summary>Traduzioni</summary>
<p><b>Senza compenso, con una proposta:</b></p>
<ol>
<li>Apri l'originale.</li>
<li>Se ti serve aiuto, premi <b>Translate</b> e poi <b>Copy prompt + text</b>, incolla in Claude e considera il risultato una bozza. Qualcuno che conosce bene l'urdu deve sempre rileggerla.</li>
<li>Quando è pronta, premi <b>+ Add a related version</b> sull'originale.</li>
<li>Controlla la lingua, scrivi il titolo in quella lingua, aggiungi il testo e premi <b>Send for review</b>.</li>
</ol>
<p><b>Con un compenso, con un task:</b> un Coordinatore crea un task di traduzione sull'originale, lo prende chi ha la qualifica di traduttore, e segue <a href="#" data-help-guide="tasks">il percorso di un task</a>.</p>
<p>Non usare entrambe le vie per lo stesso testo.</p>
</details>
<details><summary>Formati dei file</summary>
<table><tr><th>Che cosa</th><th>Accettato</th><th>Limite</th><th>Da sapere</th></tr>
<tr><td>Testo</td><td>Incollato, o Word <code>.docx</code></td><td>Word fino a 20 MB</td><td>Si conserva solo il testo: impaginazione e immagini si perdono. Caselle di testo o note possono non passare, quindi confrontalo con l'originale</td></tr>
<tr><td>PDF</td><td><code>.pdf</code></td><td>50 MB</td><td>Da solo non si trova cercando nel testo</td></tr>
<tr><td>Audio</td><td>MP3, M4A, AAC, OGG, WEBM</td><td>25 MB</td><td>MP3 e M4A sono i più sicuri. WAV è rifiutato. Serve il nome del lettore in <b>Read by</b></td></tr>
<tr><td>Video</td><td>Un link <code>https</code> a YouTube o Google Drive</td><td>Nessun file caricato</td><td>Conserva l'originale su Drive</td></tr></table>
<p>Word vecchio <code>.doc</code>: salvalo prima come <code>.docx</code>. Immagini: salvale in un PDF. InPage <code>.inp</code>: convertilo prima, come spiegato sotto.</p>
</details>
<details><summary>Convertire un file InPage</summary>
<p>I testi urdu in InPage devono diventare Unicode prima di entrare in archivio. Il file resta sul tuo computer: la conversione avviene nel browser.</p>
<ol>
<li>Apri <b>InPage Converter</b> e scegli il file <code>.inp</code>.</li>
<li>Se vuoi, compila <b>Document ID</b> e <b>English reference</b>: compaiono in testa al file Word e al PDF.</li>
<li>Premi <b>Convert</b>. Il testo compare nella casella.</li>
<li><b>Rileggilo e correggilo lì.</b> La conversione è automatica, quindi può contenere errori.</li>
<li>Il modo più semplice: copia il testo e incollalo in <b>Text</b> nella scheda. Oppure premi <b>Download Word (.docx)</b> e caricalo con <b>Or load the text from Word</b>, o <b>Generate PDF (print)</b> e scegli <b>Salva come PDF</b>.</li>
</ol>
<p>Word e PDF usano il carattere Jameel Noori Nastaleeq: installalo sul computer. Il campo <b>Google Drive folder</b> è facoltativo: carica i file su Drive, sovrascrivendo quelli con lo stesso nome.</p>
</details>
<p><a class="btn" href="#" data-tab="proposals">Apri Proposals</a></p>$help_guide$, 40, now(), 'migration 116');

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, updated_at, updated_by_email)
values ('read-aloud_en', 'read-aloud', 'en', null, 'Read a text aloud', 'Choose a text, record, send', 'add', array['operator'], $help_guide$<p class="lead">Anyone registered can read a text aloud and record it with their phone. This brings the texts to people who find reading difficult or cannot read.</p>
<p>Someone on the team listens to the recording. If they approve it, the <b>Listen</b> button appears on the text with the reader's name. No audition is needed. A reading earns no credits by itself: anyone who would like a compensation agrees with the team first, and the team creates a task.</p>
<h2>The steps</h2>
<ol>
<li><b>Choose the text.</b> Open <b>Read aloud</b> and, under <b>Texts waiting for a voice</b>, press <b>Read this</b>. Or open a text and press <b>Read aloud</b>.</li>
<li><b>Accept the consent, the first time only.</b> It explains who will listen and that your name will be shown. The name comes from your profile: if it's missing, add it in <b>My Profile</b>. Then press <b>I agree, continue</b>.</li>
<li><b>The text is now yours for 7 days.</b> If you leave, you'll find it under <b>Texts you are holding</b>, with <b>Record</b> to go back to it and <b>Let it go</b> to give it up. For your first reading you can hold one text at a time, later up to three.</li>
<li><b>Try 10 seconds.</b> Press <b>Try now</b>, allow the microphone if the phone asks, and read a line. Listen to check that your voice is clear. The trial isn't kept.</li>
<li><b>Record.</b> Press <b>Start recording</b>, with the text on the screen. Use <b>Pause</b> and <b>Continue</b> between paragraphs, then <b>Finish</b>. Keep the screen on. Recording stops by itself after 45 minutes.</li>
<li><b>Listen back.</b> If it's good, press <b>Send to be heard</b>. If not, <b>Record again</b> deletes the recording and starts over.</li>
<li><b>Follow your reading.</b> Under <b>My readings</b> it shows as <b>Waiting to be heard</b>. After 3 days you can press <b>Send a reminder</b>, then once every 3 days.</li>
</ol>
<details><summary>If you prefer your phone's own recorder</summary>
<p>At step 5, use <b>Or upload a recording made with your phone</b>. MP3, M4A, AAC, OGG and WEBM are accepted, up to 25 MB. MP3 and M4A are the safest choice. WAV is refused because the files are too large.</p>
</details>
<details><summary>If something interrupts you</summary>
<p>A phone call, another tab or a closed page costs you at most the last few seconds. When you come back to the same text on the same phone, the app offers the recording it found, to listen to and send. On a weak connection, sending tries up to three times, and the file stays on the phone until it arrives.</p>
</details>
<details><summary>Which texts can be recorded</summary>
<p>The list shows up to 20 texts, each with its language and an estimated length. A text can be recorded if:</p>
<ul>
<li>it is a written text that everyone can see, not reserved;</li>
<li>it has been reread, or it is one of Stella's texts;</li>
<li>it has no reading yet in the same language;</li>
<li>nobody is holding it or has it in review;</li>
<li>it fits your length limit: 4,000 characters before your first approved reading, then 20,000.</li>
</ul>
<p>Words of Life come first, then everything else, and within each group the shortest first. You can also start from any text: the <b>Read aloud</b> button appears only if the text can be recorded.</p>
</details>
<details><summary>What the listener can decide</summary>
<ul>
<li><b>OK, publish</b>, or <b>OK, with a note</b>: it is published at once.</li>
<li><b>Ask to record again</b>: you see the note and record again, with no consequences. The text stays yours for another 7 days.</li>
<li><b>Not accepted</b>: you see the reason and the text is free again.</li>
</ul>
</details>
<details><summary>If you change your mind</summary>
<p><b>Withdraw my consent</b>, at the bottom of <b>Read aloud</b>, removes all your readings at once. Readings still waiting are discarded, held texts become free again, and the files are erased. Anyone who can't do this themselves can ask an Admin.</p>
<p>A copy someone has already saved on their own device can't be called back. The archive's log keeps a record of the action, but not the voice.</p>
</details>
<p><a class="btn" href="#" data-tab="readings">Open Read aloud</a></p>$help_guide$, 50, now(), 'migration 116');

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, updated_at, updated_by_email)
values ('read-aloud_it', 'read-aloud', 'it', null, 'Leggere un testo ad alta voce', 'Scegli un testo, registra, invia', 'add', array['operator'], $help_guide$<p class="lead">Chiunque sia registrato può leggere un testo ad alta voce e registrarlo col telefono. Così i testi arrivano a chi fa fatica a leggere o non sa leggere.</p>
<p>Qualcuno del team ascolta la registrazione. Se la approva, sul testo compare il pulsante <b>Listen</b> con il nome di chi ha letto. Non serve un'audizione. Una lettura non dà crediti di per sé: chi desidera un compenso si accorda prima con il team, che crea un task.</p>
<h2>I passi</h2>
<ol>
<li><b>Scegli il testo.</b> Apri <b>Read aloud</b> e, sotto <b>Texts waiting for a voice</b>, premi <b>Read this</b>. Oppure apri un testo e premi <b>Read aloud</b>.</li>
<li><b>Accetta il consenso, solo la prima volta.</b> Spiega chi ascolterà e che il tuo nome sarà mostrato. Il nome viene dal tuo profilo: se manca, aggiungilo in <b>My Profile</b>. Poi premi <b>I agree, continue</b>.</li>
<li><b>Il testo è tuo per 7 giorni.</b> Se esci, lo trovi sotto <b>Texts you are holding</b>, con <b>Record</b> per tornarci e <b>Let it go</b> per lasciarlo. Per la prima lettura puoi tenere un testo alla volta, poi fino a tre.</li>
<li><b>Prova 10 secondi.</b> Premi <b>Try now</b>, consenti il microfono se il telefono lo chiede, e leggi una riga. Riascolta per controllare che la voce sia chiara. La prova non viene conservata.</li>
<li><b>Registra.</b> Premi <b>Start recording</b>, con il testo sullo schermo. Usa <b>Pause</b> e <b>Continue</b> tra i paragrafi, poi <b>Finish</b>. Tieni lo schermo acceso. La registrazione si ferma da sola dopo 45 minuti.</li>
<li><b>Riascolta.</b> Se va bene, premi <b>Send to be heard</b>. Altrimenti <b>Record again</b> cancella la registrazione e ricomincia.</li>
<li><b>Segui la tua lettura.</b> Sotto <b>My readings</b> compare come <b>Waiting to be heard</b>. Dopo 3 giorni puoi premere <b>Send a reminder</b>, poi una volta ogni 3 giorni.</li>
</ol>
<details><summary>Se preferisci il registratore del telefono</summary>
<p>Al passo 5, usa <b>Or upload a recording made with your phone</b>. Sono accettati MP3, M4A, AAC, OGG e WEBM, fino a 25 MB. MP3 e M4A sono la scelta più sicura. WAV è rifiutato perché i file sono troppo grandi.</p>
</details>
<details><summary>Se qualcosa ti interrompe</summary>
<p>Una telefonata, un'altra scheda o una pagina chiusa ti costano al massimo gli ultimi secondi. Quando torni allo stesso testo sullo stesso telefono, l'app ti propone la registrazione che ha trovato, da riascoltare e inviare. Con una connessione debole l'invio riprova fino a tre volte, e il file resta sul telefono finché non arriva.</p>
</details>
<details><summary>Quali testi si possono registrare</summary>
<p>L'elenco mostra fino a 20 testi, ciascuno con la lingua e una durata stimata. Un testo si può registrare se:</p>
<ul>
<li>è un testo scritto che tutti possono vedere, non riservato;</li>
<li>è stato riletto, oppure è uno dei testi di Stella;</li>
<li>non ha ancora una lettura nella stessa lingua;</li>
<li>nessuno lo sta tenendo o lo ha in revisione;</li>
<li>rientra nel tuo limite di lunghezza: 4.000 caratteri prima della tua prima lettura approvata, poi 20.000.</li>
</ul>
<p>Prima vengono le Parole di Vita, poi tutto il resto, e in ogni gruppo prima i più corti. Puoi anche partire da qualsiasi testo: il pulsante <b>Read aloud</b> compare solo se il testo si può registrare.</p>
</details>
<details><summary>Che cosa può decidere chi ascolta</summary>
<ul>
<li><b>OK, publish</b>, oppure <b>OK, with a note</b>: viene pubblicata subito.</li>
<li><b>Ask to record again</b>: vedi la nota e registri di nuovo, senza conseguenze. Il testo resta tuo per altri 7 giorni.</li>
<li><b>Not accepted</b>: vedi il motivo e il testo torna libero.</li>
</ul>
</details>
<details><summary>Se cambi idea</summary>
<p><b>Withdraw my consent</b>, in fondo a <b>Read aloud</b>, toglie subito tutte le tue letture. Quelle in attesa vengono scartate, i testi tenuti tornano liberi e i file vengono cancellati. Chi non può farlo da solo può chiederlo a un Admin.</p>
<p>Una copia già salvata sul dispositivo di qualcuno non si può richiamare. Il registro dell'archivio conserva traccia dell'azione, ma non la voce.</p>
</details>
<p><a class="btn" href="#" data-tab="readings">Apri Read aloud</a></p>$help_guide$, 50, now(), 'migration 116');

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, updated_at, updated_by_email)
values ('tasks_en', 'tasks', 'en', null, 'Work on a task', 'Claim, submit, credits, reputation', 'work', array['operator'], $help_guide$<p class="lead">A task is an agreed piece of work with a value in credits: you take it, do it and hand it in, and the credits arrive only once the work has been checked and approved.</p>
<p>A Coordinator or Admin creates it, often on a specific document. To add a text with no compensation, use <a href="#" data-help-guide="propose">Proposals</a> instead.</p>
<h2>The steps</h2>
<ol>
<li><b>Find a task.</b> <b>Tasks Store</b> shows open work with its category, credits and title. You can filter by <b>Category</b> and <b>Min credits</b>.</li>
<li><b>Take it.</b> Press <b>Claim</b>, choose <b>Your target due date</b> and confirm. The date is a commitment: it can't be changed afterwards, so choose a realistic one.</li>
<li><b>Download the original.</b> In <b>My Tasks → In progress</b>, press <b>Download original file</b>. If it's missing, tell whoever created the task.</li>
<li><b>Do the work</b> on your computer, following the task's description.</li>
<li><b>Upload the result.</b> Press <b>Upload corrected file</b>: <code>.inp</code>, <code>.doc</code>, <code>.docx</code> and <code>.pdf</code> are accepted. Until you submit, you can replace it.</li>
<li><b>Submit.</b> Press <b>Submit for review</b> and confirm. If the task concerns a document, the button works only after the upload. From here on you can't change anything.</li>
<li><b>Wait.</b> The task moves to <b>Waiting for review</b>.</li>
<li><b>Read the outcome.</b> <b>Closed</b> shows the result and any note from the reviewer. Credits appear under <b>My credits</b> and in the top bar.</li>
</ol>
<details><summary>Kinds of task, and who can take them</summary>
<table><tr><th>Work</th><th>Category in the app</th><th>Who can take it</th></tr>
<tr><td>Translation</td><td>Italian to Urdu, English to Urdu</td><td>Translator qualification</td></tr>
<tr><td>Typing</td><td>Typing</td><td>Any Operator</td></tr>
<tr><td>Proofreading</td><td>Proof Reading</td><td>Any Operator</td></tr>
<tr><td>Revision</td><td>Revision</td><td>Revisor qualification</td></tr>
<tr><td>Other</td><td>Content Creation, Others</td><td>Any Operator</td></tr></table>
<p>What counts is the value written on the task. Don't confuse a <b>Revision</b> task, which is work on a text with its own credits, with a Revisor's verdict, which checks other people's tasks and earns no credits.</p>
</details>
<details><summary>After submitting: two checks</summary>
<p><b>First check, the Revisor.</b> A Revisor or Coordinator does this, never on their own task, without seeing who did the work.</p>
<table><tr><th>Verdict</th><th>Meaning</th><th>What happens</th></tr>
<tr><td><b>OK</b></td><td>The work is good</td><td>It goes to Admin</td></tr>
<tr><td><b>OK, but...</b></td><td>Good, with some remarks</td><td>It goes to Admin, with a small reputation penalty at closing</td></tr>
<tr><td><b>Fail</b></td><td>Not good enough</td><td>The task closes: no credits, less reputation. An identical new task appears, open to others but not to you</td></tr></table>
<p><b>Second check, Admin.</b> While waiting, the task shows as <b>Approved</b>. <b>Publish</b> closes it: the credits are added and your reputation changes according to the verdict. <b>Reject</b> closes it despite the positive verdict, with a reason: no credits and the same penalty as a Fail.</p>
<p>When the task concerns a document, Admin then prepares the final PDF and publishes the new version. Your credits don't depend on this step.</p>
</details>
<details><summary>Credits</summary>
<p>A task's credits are its rate times its pages, plus any extras, and they are added only once, when Admin presses <b>Publish</b>. A Coordinator can add extra credits for difficulty or urgency, giving the reason; above a certain threshold, the Coordination lead must approve them.</p>
<p><b>My Tasks → My credits</b> shows <b>Earned</b>, <b>In progress</b> (not yet added) and <b>Redeemed</b> (tasks closed with Publish, which doesn't mean paid).</p>
<p>In this first phase the work is voluntary and credits don't convert into money. Later a credit will have a value, the same for everyone, set according to the funds raised. Rates and payments are still to be decided.</p>
</details>
<details><summary>Reputation</summary>
<p>A score from 0 to 100 that starts at 50 and reflects how reliable your work is. You see it in the top bar. It changes only through recorded events, and a large task weighs more than a small one. The values are still to be decided.</p>
<ul>
<li><b>OK:</b> goes up. <b>OK, but...:</b> goes down a little. <b>Fail</b> or <b>Reject:</b> goes down more.</li>
<li><b>Give up this task</b>, or a Coordinator reassigning it: no change.</li>
<li>A Coordinator taking it back with <b>Free up</b>, or misuse of a board: goes down.</li>
</ul>
<p>No limit applies by itself: reputation doesn't stop you taking tasks. If it falls low, HR and the Coordinators see it. The point is to talk with you, not to punish you.</p>
</details>
<details><summary>If something goes wrong</summary>
<ul>
<li><b>You can't finish:</b> press <b>Give up this task</b> and write the reason. The task becomes free again, with no penalty. You can do this only before submitting.</li>
<li><b>You're late:</b> the task shows as <b>Overdue</b>. There is no automatic penalty and the date can't be moved: tell the team. If you don't reply, a Coordinator can take it back with <b>Free up</b>, and you lose reputation.</li>
<li><b>You uploaded the wrong file:</b> before submitting, upload the right one. After submitting, tell a Coordinator at once.</li>
<li><b>You got a Fail or a Reject:</b> read the note under <b>Closed</b>. If you disagree, talk to a Coordinator.</li>
<li><b>A task doesn't appear in the Store:</b> it may need a qualification you don't have, or be the repeat of your own Fail. HR proposes qualifications.</li>
</ul>
</details>
<p><a class="btn" href="#" data-tab="tasks">Open Tasks</a></p>$help_guide$, 60, now(), 'migration 116');

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, updated_at, updated_by_email)
values ('tasks_it', 'tasks', 'it', null, 'Lavorare su un task', 'Prendere, consegnare, crediti, reputazione', 'work', array['operator'], $help_guide$<p class="lead">Un task è un lavoro concordato con un valore in crediti: lo prendi, lo fai e lo consegni, e i crediti arrivano solo dopo che il lavoro è stato controllato e approvato.</p>
<p>Lo crea un Coordinatore o un Admin, spesso su un documento preciso. Per aggiungere un testo senza compenso, usa invece <a href="#" data-help-guide="propose">Proposals</a>.</p>
<h2>I passi</h2>
<ol>
<li><b>Trova un task.</b> <b>Tasks Store</b> mostra il lavoro libero con categoria, crediti e titolo. Puoi filtrare per <b>Category</b> e <b>Min credits</b>.</li>
<li><b>Prendilo.</b> Premi <b>Claim</b>, scegli <b>Your target due date</b> e conferma. La data è un impegno: non si può cambiare dopo, quindi scegline una realistica.</li>
<li><b>Scarica l'originale.</b> In <b>My Tasks → In progress</b>, premi <b>Download original file</b>. Se manca, avvisa chi ha creato il task.</li>
<li><b>Fai il lavoro</b> sul computer, seguendo la descrizione del task.</li>
<li><b>Carica il risultato.</b> Premi <b>Upload corrected file</b>: sono accettati <code>.inp</code>, <code>.doc</code>, <code>.docx</code> e <code>.pdf</code>. Finché non consegni, puoi sostituirlo.</li>
<li><b>Consegna.</b> Premi <b>Submit for review</b> e conferma. Se il task riguarda un documento, il pulsante funziona solo dopo il caricamento. Da qui in poi non puoi cambiare nulla.</li>
<li><b>Attendi.</b> Il task passa a <b>Waiting for review</b>.</li>
<li><b>Leggi l'esito.</b> <b>Closed</b> mostra il risultato e l'eventuale nota del revisore. I crediti compaiono sotto <b>My credits</b> e nella barra in alto.</li>
</ol>
<details><summary>Tipi di task, e chi può prenderli</summary>
<table><tr><th>Lavoro</th><th>Categoria nell'app</th><th>Chi può prenderlo</th></tr>
<tr><td>Traduzione</td><td>Italian to Urdu, English to Urdu</td><td>Qualifica di traduttore</td></tr>
<tr><td>Battitura</td><td>Typing</td><td>Qualsiasi Operatore</td></tr>
<tr><td>Correzione di bozze</td><td>Proof Reading</td><td>Qualsiasi Operatore</td></tr>
<tr><td>Revisione</td><td>Revision</td><td>Qualifica di Revisore</td></tr>
<tr><td>Altro</td><td>Content Creation, Others</td><td>Qualsiasi Operatore</td></tr></table>
<p>Conta il valore scritto sul task. Non confondere un task di <b>Revision</b>, che è un lavoro su un testo con i suoi crediti, con il verdetto di un Revisore, che controlla i task altrui e non dà crediti.</p>
</details>
<details><summary>Dopo la consegna: due controlli</summary>
<p><b>Primo controllo, il Revisore.</b> Lo fa un Revisore o un Coordinatore, mai sul proprio task, senza vedere chi ha fatto il lavoro.</p>
<table><tr><th>Verdetto</th><th>Significato</th><th>Che cosa succede</th></tr>
<tr><td><b>OK</b></td><td>Il lavoro è buono</td><td>Va all'Admin</td></tr>
<tr><td><b>OK, but...</b></td><td>Buono, con alcune osservazioni</td><td>Va all'Admin, con una piccola penalità di reputazione alla chiusura</td></tr>
<tr><td><b>Fail</b></td><td>Non abbastanza buono</td><td>Il task si chiude: niente crediti, meno reputazione. Compare un nuovo task identico, aperto agli altri ma non a te</td></tr></table>
<p><b>Secondo controllo, l'Admin.</b> Nell'attesa il task risulta <b>Approved</b>. <b>Publish</b> lo chiude: i crediti vengono aggiunti e la reputazione cambia secondo il verdetto. <b>Reject</b> lo chiude nonostante il verdetto positivo, con un motivo: niente crediti e la stessa penalità di un Fail.</p>
<p>Quando il task riguarda un documento, l'Admin prepara poi il PDF finale e pubblica la nuova versione. I tuoi crediti non dipendono da questo passo.</p>
</details>
<details><summary>Crediti</summary>
<p>I crediti di un task sono la tariffa per le pagine, più eventuali extra, e vengono aggiunti una sola volta, quando l'Admin preme <b>Publish</b>. Un Coordinatore può aggiungere crediti extra per difficoltà o urgenza, dicendo il motivo; sopra una certa soglia deve approvarli il responsabile di Coordinamento.</p>
<p><b>My Tasks → My credits</b> mostra <b>Earned</b>, <b>In progress</b> (non ancora aggiunti) e <b>Redeemed</b> (task chiusi con Publish, il che non significa pagati).</p>
<p>In questa prima fase il lavoro è volontario e i crediti non si convertono in denaro. Più avanti un credito avrà un valore, uguale per tutti, stabilito in base ai fondi raccolti. Tariffe e pagamenti sono ancora da decidere.</p>
</details>
<details><summary>Reputazione</summary>
<p>Un punteggio da 0 a 100 che parte da 50 e riflette quanto è affidabile il tuo lavoro. Lo vedi nella barra in alto. Cambia solo con eventi registrati, e un task grande pesa più di uno piccolo. I valori sono ancora da decidere.</p>
<ul>
<li><b>OK:</b> sale. <b>OK, but...:</b> scende un poco. <b>Fail</b> o <b>Reject:</b> scende di più.</li>
<li><b>Give up this task</b>, o un Coordinatore che lo riassegna: nessun cambiamento.</li>
<li>Un Coordinatore che lo riprende con <b>Free up</b>, o un abuso di una bacheca: scende.</li>
</ul>
<p>Nessun limite scatta da solo: la reputazione non ti impedisce di prendere task. Se scende molto, HR e i Coordinatori lo vedono. Lo scopo è parlare con te, non punirti.</p>
</details>
<details><summary>Se qualcosa va storto</summary>
<ul>
<li><b>Non riesci a finire:</b> premi <b>Give up this task</b> e scrivi il motivo. Il task torna libero, senza penalità. Puoi farlo solo prima di consegnare.</li>
<li><b>Sei in ritardo:</b> il task risulta <b>Overdue</b>. Non c'è penalità automatica e la data non si sposta: avvisa il team. Se non rispondi, un Coordinatore può riprenderlo con <b>Free up</b>, e perdi reputazione.</li>
<li><b>Hai caricato il file sbagliato:</b> prima di consegnare, carica quello giusto. Dopo, avvisa subito un Coordinatore.</li>
<li><b>Hai ricevuto un Fail o un Reject:</b> leggi la nota sotto <b>Closed</b>. Se non sei d'accordo, parla con un Coordinatore.</li>
<li><b>Un task non compare nello Store:</b> può richiedere una qualifica che non hai, o essere la ripetizione di un tuo Fail. Le qualifiche le propone HR.</li>
</ul>
</details>
<p><a class="btn" href="#" data-tab="tasks">Apri Tasks</a></p>$help_guide$, 60, now(), 'migration 116');

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, updated_at, updated_by_email)
values ('talk-team_en', 'talk-team', 'en', null, 'Talk to the team', 'Report, share, join, your profile', 'work', array['user'], $help_guide$<p class="lead">There are different places for different things, so that nothing gets lost.</p>
<table><tr><th>You want to</th><th>Go to</th></tr>
<tr><td>Report a mistake, a file that won't open, a suggestion</td><td><b>Report a Problem or Suggestion</b></td></tr>
<tr><td>Share an experience, a difficulty, an idea</td><td><b>Share with us</b></td></tr>
<tr><td>Join the team that works on the archive</td><td><b>Join the Team</b> (Users only)</td></tr>
<tr><td>Change your name, password or other details</td><td><b>My Profile</b></td></tr></table>
<h2>Report a problem</h2>
<ol>
<li>Choose the <b>Report type</b> and write your message. If it concerns a document, add its number, or press <b>Report a problem</b> on the document itself.</li>
<li>Press <b>Send</b>. The Coordinators and Admins read it and reply on the same page. You see a notice when a reply arrives.</li>
</ol>
<h2>Share with us</h2>
<p>This isn't for technical problems. It is for what you live and think, and every department lead reads it. Write, or press <b>Record a voice message</b> if your phone allows it. You see any thanks and replies on the same page.</p>
<details><summary>Join the Team</summary>
<p>Fill in the form with your experience, availability, skills and motivation, and press <b>Submit Request</b>. HR reads it and may contact you; an Admin gives the final approval. If you are accepted you become an Operator and new tabs appear.</p>
</details>
<details><summary>My Profile</summary>
<ul>
<li><b>Change my password</b> and <b>Sign out</b>.</li>
<li><b>My Certificates</b>, from the formation paths.</li>
<li><b>My activity in the archive</b>: what you have changed. Only you, Admin and the HR lead can see it.</li>
</ul>
</details>
<p><a class="btn" href="#" data-tab="profile">Open My Profile</a></p>$help_guide$, 70, now(), 'migration 116');

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, updated_at, updated_by_email)
values ('talk-team_it', 'talk-team', 'it', null, 'Parlare con il team', 'Segnalare, condividere, unirsi, il tuo profilo', 'work', array['user'], $help_guide$<p class="lead">Ci sono posti diversi per cose diverse, così nulla va perso.</p>
<table><tr><th>Vuoi</th><th>Vai in</th></tr>
<tr><td>Segnalare un errore, un file che non si apre, un suggerimento</td><td><b>Report a Problem or Suggestion</b></td></tr>
<tr><td>Condividere un'esperienza, una difficoltà, un'idea</td><td><b>Share with us</b></td></tr>
<tr><td>Entrare nel team che lavora all'archivio</td><td><b>Join the Team</b> (solo User)</td></tr>
<tr><td>Cambiare nome, password o altri dati</td><td><b>My Profile</b></td></tr></table>
<h2>Segnalare un problema</h2>
<ol>
<li>Scegli il <b>Report type</b> e scrivi il messaggio. Se riguarda un documento, aggiungi il numero, oppure premi <b>Report a problem</b> sul documento stesso.</li>
<li>Premi <b>Send</b>. Coordinatori e Admin lo leggono e rispondono nella stessa pagina. Vedi un avviso quando arriva una risposta.</li>
</ol>
<h2>Share with us</h2>
<p>Non è per i problemi tecnici. È per ciò che vivi e pensi, e lo leggono tutti i responsabili di reparto. Scrivi, oppure premi <b>Record a voice message</b> se il telefono lo consente. Ringraziamenti e risposte li vedi nella stessa pagina.</p>
<details><summary>Join the Team</summary>
<p>Compila il modulo con esperienza, disponibilità, competenze e motivazione, e premi <b>Submit Request</b>. HR lo legge e può contattarti; un Admin dà l'approvazione finale. Se vieni accettato diventi Operatore e compaiono nuove schede.</p>
</details>
<details><summary>My Profile</summary>
<ul>
<li><b>Change my password</b> e <b>Sign out</b>.</li>
<li><b>My Certificates</b>, dai percorsi formativi.</li>
<li><b>My activity in the archive</b>: ciò che hai modificato. Lo vedono solo tu, gli Admin e il responsabile di HR.</li>
</ul>
</details>
<p><a class="btn" href="#" data-tab="profile">Apri My Profile</a></p>$help_guide$, 70, now(), 'migration 116');

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, updated_at, updated_by_email)
values ('review-proposals_en', 'review-proposals', 'en', null, 'Review proposals', 'Approve, send back or reject', 'check', array['qual:REVISOR', 'coordinator', 'dept:FORM'], $help_guide$<p class="lead">Your approval alone publishes a proposal, so nothing reaches the archive without a second pair of eyes. You can't decide on your own proposals.</p>
<h2>The steps</h2>
<ol>
<li><b>Open the queue.</b> <b>Proposals → To review</b>, oldest first. You don't see who proposed it.</li>
<li><b>Open a proposal.</b> You see the data all versions share, then each version with its text, PDF, audio or video.</li>
<li><b>If you need time, press Take it.</b> It holds the proposal for you for 48 hours, then it returns to the queue by itself. <b>Release it</b> lets it go sooner.</li>
<li><b>Check.</b> Is it really new, or already in the archive? Are the title, author and date right? For a Word of Life, is it its own month? Is the access level right?</li>
<li><b>Read the text</b> against its source, if you can, and tick that you have. Only then does that text count as reread. Otherwise it stays unverified, which is allowed.</li>
<li><b>Decide.</b></li>
</ol>
<table><tr><th>Button</th><th>When</th><th>What happens</th></tr>
<tr><td><b>Approve and publish</b></td><td>It is right</td><td>Every version becomes visible at once, according to its access level</td></tr>
<tr><td><b>Send back to correct</b></td><td>It can be fixed</td><td>The proposer sees your note and can send it again</td></tr>
<tr><td><b>Reject</b></td><td>It doesn't belong in the archive</td><td>The proposer sees the reason. It is closed</td></tr></table>
<details><summary>Reserved documents</summary>
<p>A reserved proposal can be reviewed only by another Formation member or an Admin. If you aren't one of them, it doesn't reach you.</p>
</details>
<details><summary>So that nothing stays stuck</summary>
<p>The proposer can send a reminder after 3 days, and it reaches the queue, not one person. After 7 days a proposal is marked as overdue. Everything happens inside the app, with no email, so look at the queue regularly.</p>
</details>
<details><summary>After you publish</summary>
<p>An Admin copies any PDF to Drive from <b>Files for Drive</b>. An Admin can also withdraw a document later. Everything you did stays in the log.</p>
</details>
<p><a class="btn" href="#" data-tab="proposals">Open Proposals</a></p>$help_guide$, 80, now(), 'migration 116');

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, updated_at, updated_by_email)
values ('review-proposals_it', 'review-proposals', 'it', null, 'Rivedere le proposte', 'Approvare, rimandare o respingere', 'check', array['qual:REVISOR', 'coordinator', 'dept:FORM'], $help_guide$<p class="lead">La tua sola approvazione pubblica una proposta: così nulla entra in archivio senza un secondo sguardo. Non puoi decidere sulle tue proposte.</p>
<h2>I passi</h2>
<ol>
<li><b>Apri la coda.</b> <b>Proposals → To review</b>, le più vecchie in cima. Non vedi chi ha proposto.</li>
<li><b>Apri una proposta.</b> Vedi i dati comuni, poi ogni versione con il suo testo, PDF, audio o video.</li>
<li><b>Se ti serve tempo, premi Take it.</b> Tiene la proposta per te per 48 ore, poi torna da sola in coda. <b>Release it</b> la lascia prima.</li>
<li><b>Controlla.</b> È davvero nuova, o è già in archivio? Titolo, autore e data sono giusti? Per una Parola di Vita, è il suo mese? Il livello di accesso è giusto?</li>
<li><b>Leggi il testo</b> a fronte della fonte, se puoi, e spunta di averlo fatto. Solo allora quel testo risulta riletto. Altrimenti resta non verificato, ed è ammesso.</li>
<li><b>Decidi.</b></li>
</ol>
<table><tr><th>Pulsante</th><th>Quando</th><th>Che cosa succede</th></tr>
<tr><td><b>Approve and publish</b></td><td>È a posto</td><td>Ogni versione diventa subito visibile, secondo il suo livello di accesso</td></tr>
<tr><td><b>Send back to correct</b></td><td>Si può sistemare</td><td>Chi ha proposto vede la tua nota e può inviarla di nuovo</td></tr>
<tr><td><b>Reject</b></td><td>Non è da archivio</td><td>Chi ha proposto vede il motivo. Si chiude</td></tr></table>
<details><summary>Documenti riservati</summary>
<p>Una proposta riservata può essere rivista solo da un altro membro di Formazione o da un Admin. Se non sei tra loro, non ti arriva.</p>
</details>
<details><summary>Perché nulla resti fermo</summary>
<p>Chi propone può mandare un promemoria dopo 3 giorni, e arriva alla coda, non a una persona. Dopo 7 giorni una proposta è segnata come in ritardo. Tutto avviene dentro l'app, senza email, quindi guarda la coda con regolarità.</p>
</details>
<details><summary>Dopo la pubblicazione</summary>
<p>Un Admin copia l'eventuale PDF su Drive da <b>Files for Drive</b>. Un Admin può anche ritirare un documento in seguito. Tutto ciò che hai fatto resta nel registro.</p>
</details>
<p><a class="btn" href="#" data-tab="proposals">Apri Proposals</a></p>$help_guide$, 80, now(), 'migration 116');

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, updated_at, updated_by_email)
values ('review-tasks_en', 'review-tasks', 'en', null, 'Review tasks', 'Verdicts: OK, OK but, Fail', 'check', array['qual:REVISOR', 'coordinator'], $help_guide$<p class="lead">A verdict checks a colleague's finished task. It earns no credits, and it doesn't close the task: an Admin does that after you.</p>
<h2>The steps</h2>
<ol>
<li><b>Open Tasks → Review Tasks.</b> Tasks appear without the name of who did them, and your own never appear there.</li>
<li><b>Open the corrected file</b> with <b>Open corrected file</b>, if the task concerns a document, and compare it with what was asked.</li>
<li><b>Give your verdict,</b> with a note that helps the person do better next time.</li>
</ol>
<table><tr><th>Verdict</th><th>Meaning</th><th>What happens</th></tr>
<tr><td><b>OK</b></td><td>Done well</td><td>It goes to Admin</td></tr>
<tr><td><b>OK, but...</b></td><td>Acceptable, with remarks: say which</td><td>It goes to Admin, with a small reputation penalty at closing</td></tr>
<tr><td><b>Fail</b></td><td>It needs redoing</td><td>It closes with no credits and less reputation. A new task appears for someone else</td></tr></table>
<details><summary>When a positive verdict is refused</summary>
<p>If a task carries extra credits above the threshold, the Coordination lead must approve them first. Until then OK and OK, but... are refused. The task isn't lost: ask the lead.</p>
</details>
<details><summary>Why it is anonymous</summary>
<p>So that the judgement falls on the work, not on the person. Write as you would to someone you esteem.</p>
</details>
<p><a class="btn" href="#" data-tab="tasks">Open Tasks</a></p>$help_guide$, 90, now(), 'migration 116');

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, updated_at, updated_by_email)
values ('review-tasks_it', 'review-tasks', 'it', null, 'Rivedere i task', 'Verdetti: OK, OK but, Fail', 'check', array['qual:REVISOR', 'coordinator'], $help_guide$<p class="lead">Un verdetto controlla il task finito di un collega. Non dà crediti e non chiude il task: lo fa un Admin dopo di te.</p>
<h2>I passi</h2>
<ol>
<li><b>Apri Tasks → Review Tasks.</b> I task compaiono senza il nome di chi li ha fatti, e i tuoi non compaiono mai.</li>
<li><b>Apri il file corretto</b> con <b>Open corrected file</b>, se il task riguarda un documento, e confrontalo con ciò che era richiesto.</li>
<li><b>Dai il verdetto,</b> con una nota che aiuti la persona a far meglio la prossima volta.</li>
</ol>
<table><tr><th>Verdetto</th><th>Significato</th><th>Che cosa succede</th></tr>
<tr><td><b>OK</b></td><td>Fatto bene</td><td>Va all'Admin</td></tr>
<tr><td><b>OK, but...</b></td><td>Accettabile, con osservazioni: di' quali</td><td>Va all'Admin, con una piccola penalità di reputazione alla chiusura</td></tr>
<tr><td><b>Fail</b></td><td>Va rifatto</td><td>Si chiude senza crediti e con meno reputazione. Compare un nuovo task per qualcun altro</td></tr></table>
<details><summary>Quando un verdetto positivo è rifiutato</summary>
<p>Se un task porta crediti extra sopra la soglia, deve approvarli prima il responsabile di Coordinamento. Fino ad allora OK e OK, but... sono rifiutati. Il task non è perso: chiedi al responsabile.</p>
</details>
<details><summary>Perché è anonimo</summary>
<p>Perché il giudizio cada sul lavoro, non sulla persona. Scrivi come scriveresti a qualcuno che stimi.</p>
</details>
<p><a class="btn" href="#" data-tab="tasks">Apri Tasks</a></p>$help_guide$, 90, now(), 'migration 116');

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, updated_at, updated_by_email)
values ('listen-readings_en', 'listen-readings', 'en', null, 'Listen to readings', 'Publish a reading or ask again', 'check', array['qual:AUDIO_REVIEWER', 'coordinator'], $help_guide$<p class="lead">Publishing a reading takes one decision by one team member, who isn't the person who read. Those with the <code>AUDIO_REVIEWER</code> qualification, Coordinators and Admins can decide.</p>
<h2>The steps</h2>
<ol>
<li><b>Open the queue.</b> <b>Read aloud → To listen</b>, oldest first. The reader's name isn't shown, though a voice can be recognised. A mark shows those waiting for over 7 days.</li>
<li><b>Open a reading.</b> Press <b>Listen</b>: you get the audio player and, below it, the text. If the text was corrected after the recording, a notice tells you.</li>
<li><b>If you need time, press Take it.</b> It holds the reading for 48 hours, then it returns to the queue. <b>Release it</b> lets it go sooner.</li>
<li><b>Listen all the way through, following the text, and decide.</b></li>
</ol>
<table><tr><th>Button</th><th>When</th><th>What happens</th></tr>
<tr><td><b>OK, publish</b></td><td>The reading is good</td><td>Published at once</td></tr>
<tr><td><b>OK, with a note</b></td><td>It is good, and you have something to say</td><td>Published at once, and the reader sees the note</td></tr>
<tr><td><b>Ask to record again</b></td><td>It can be improved</td><td>The reader records again, with no consequences. The text stays held for another 7 days</td></tr>
<tr><td><b>Not accepted</b></td><td>It can't be used</td><td>The reader sees the reason and the text is free again. The file is erased after 30 days</td></tr></table>
<p>A note is required for the last two. Please write it kindly: the reader is a volunteer.</p>
<p><a class="btn" href="#" data-tab="readings">Open Read aloud</a></p>$help_guide$, 100, now(), 'migration 116');

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, updated_at, updated_by_email)
values ('listen-readings_it', 'listen-readings', 'it', null, 'Ascoltare le letture', 'Pubblicare una lettura o chiederla di nuovo', 'check', array['qual:AUDIO_REVIEWER', 'coordinator'], $help_guide$<p class="lead">Per pubblicare una lettura basta una decisione di una persona del team, diversa da chi ha letto. Possono decidere chi ha la qualifica <code>AUDIO_REVIEWER</code>, i Coordinatori e gli Admin.</p>
<h2>I passi</h2>
<ol>
<li><b>Apri la coda.</b> <b>Read aloud → To listen</b>, le più vecchie in cima. Il nome di chi legge non è mostrato, anche se una voce si può riconoscere. Un segno indica quelle in attesa da oltre 7 giorni.</li>
<li><b>Apri una lettura.</b> Premi <b>Listen</b>: hai il lettore audio e, sotto, il testo. Se il testo è stato corretto dopo la registrazione, un avviso te lo dice.</li>
<li><b>Se ti serve tempo, premi Take it.</b> Tiene la lettura per 48 ore, poi torna in coda. <b>Release it</b> la lascia prima.</li>
<li><b>Ascolta fino in fondo, seguendo il testo, e decidi.</b></li>
</ol>
<table><tr><th>Pulsante</th><th>Quando</th><th>Che cosa succede</th></tr>
<tr><td><b>OK, publish</b></td><td>La lettura è buona</td><td>Pubblicata subito</td></tr>
<tr><td><b>OK, with a note</b></td><td>È buona, e hai qualcosa da dire</td><td>Pubblicata subito, e chi legge vede la nota</td></tr>
<tr><td><b>Ask to record again</b></td><td>Si può migliorare</td><td>Chi legge registra di nuovo, senza conseguenze. Il testo resta tenuto per altri 7 giorni</td></tr>
<tr><td><b>Not accepted</b></td><td>Non si può usare</td><td>Chi legge vede il motivo e il testo torna libero. Il file viene cancellato dopo 30 giorni</td></tr></table>
<p>Per gli ultimi due serve una nota. Scrivila con gentilezza: chi legge è un volontario.</p>
<p><a class="btn" href="#" data-tab="readings">Apri Read aloud</a></p>$help_guide$, 100, now(), 'migration 116');

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, updated_at, updated_by_email)
values ('moderate-board_en', 'moderate-board', 'en', null, 'Look after a board', 'Publish, reject, propose for the archive', 'check', array['board_editor', 'coordinator'], $help_guide$<p class="lead">The editors of a board read what Users submit and keep the board faithful to its purpose. You are named board by board, by a Coordinator or Admin.</p>
<h2>What you do</h2>
<ol>
<li><b>Open your board.</b> A queue shows the posts waiting for you.</li>
<li><b>Press Publish</b> or <b>Reject</b>. A rejection needs a short note, which the author sees.</li>
<li><b>Look at suggestions for the archive.</b> <b>Propose for archive</b> opens the proposal form already filled in; <b>Not for the archive</b> declines it.</li>
</ol>
<p>Your own posts appear at once. To attach an archive document, open it and press <b>+ Board</b>.</p>
<details><summary>Editing and removing</summary>
<p>You can edit any post on your board, and delete your own. To delete someone else's post, ask a Coordinator or Admin, who must give the reason. They can also <b>Pin</b> a post to keep it at the top.</p>
</details>
<details><summary>Repeated misuse</summary>
<p>You don't decide this alone. You propose it, and a Formation or HR lead approves it: a reputation penalty for an Operator, or a block on posting for a User. A written reason is always required.</p>
</details>
<details><summary>Naming editors (Coordinators and Admins)</summary>
<p>At the bottom of <b>Boards</b>, in <b>Board editors</b>: choose the board, search for the person and add them. <b>Remove</b> takes them off.</p>
</details>
<p><a class="btn" href="#" data-tab="boards">Open Boards</a></p>$help_guide$, 110, now(), 'migration 116');

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, updated_at, updated_by_email)
values ('moderate-board_it', 'moderate-board', 'it', null, 'Curare una bacheca', 'Pubblicare, rifiutare, proporre per l''archivio', 'check', array['board_editor', 'coordinator'], $help_guide$<p class="lead">Chi cura una bacheca legge ciò che inviano gli User e la mantiene fedele al suo scopo. Si viene nominati bacheca per bacheca, da un Coordinatore o un Admin.</p>
<h2>Che cosa fai</h2>
<ol>
<li><b>Apri la tua bacheca.</b> Una coda mostra i post che ti aspettano.</li>
<li><b>Premi Publish</b> o <b>Reject</b>. Un rifiuto richiede una breve nota, che l'autore vede.</li>
<li><b>Guarda i suggerimenti per l'archivio.</b> <b>Propose for archive</b> apre la scheda di proposta già compilata; <b>Not for the archive</b> lo declina.</li>
</ol>
<p>I tuoi post compaiono subito. Per allegare un documento dell'archivio, aprilo e premi <b>+ Board</b>.</p>
<details><summary>Modificare e togliere</summary>
<p>Puoi modificare qualsiasi post della tua bacheca, e cancellare i tuoi. Per cancellare il post di un altro, chiedi a un Coordinatore o a un Admin, che deve dire il motivo. Loro possono anche fissare un post in alto con <b>Pin</b>.</p>
</details>
<details><summary>Abuso ripetuto</summary>
<p>Non lo decidi da solo. Lo proponi, e lo approva il responsabile di Formazione o di HR: una penalità di reputazione per un Operatore, o il blocco delle pubblicazioni per uno User. Serve sempre un motivo scritto.</p>
</details>
<details><summary>Nominare chi cura (Coordinatori e Admin)</summary>
<p>In fondo a <b>Boards</b>, in <b>Board editors</b>: scegli la bacheca, cerca la persona e aggiungila. <b>Remove</b> la toglie.</p>
</details>
<p><a class="btn" href="#" data-tab="boards">Apri Boards</a></p>$help_guide$, 110, now(), 'migration 116');

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, updated_at, updated_by_email)
values ('build-path_en', 'build-path', 'en', null, 'Build a formation path', 'Modules, chapters, quizzes, publishing', 'check', array['dept:FORM', 'coordinator'], $help_guide$<p class="lead">Members of Formation build the paths, preferably together. A path has one owner and any number of co-authors.</p>
<h2>The steps</h2>
<ol>
<li><b>Create it.</b> <b>Formation Paths → + New path</b>: title, description, target audience, session type and, if you need them, course dates and an enrollment deadline. It starts as a draft: only those building it, other formators, Coordinators and Admins can see it.</li>
<li><b>Build the structure.</b> <b>+ Add module</b>, then <b>+ Chapter</b>, then posts. The arrows change the order.</li>
<li><b>File archive texts into it.</b> Open a document and press <b>+ Path</b>. You can create a module and chapter from there too.</li>
<li><b>Add quizzes.</b> One per module, and a final exam if you want it, each with a pass threshold.</li>
<li><b>Publish.</b> <b>Publish</b> opens it to everyone. You can keep adding afterwards.</li>
</ol>
<div class="note"><b>Delete</b> on a module, a chapter or a path has no way back, and a deleted path takes enrollments and certificates with it. To take a path out of the catalog, use <b>Archive</b>: certificates already earned stay.</div>
<details><summary>Writing a quiz with an AI tool</summary>
<ol>
<li>In the quiz, press <b>Copy AI prompt</b>.</li>
<li>Paste it into an AI tool with the module's text.</li>
<li>Read what comes back, since it is only a draft, then paste it into <b>Import quiz from Markdown</b>.</li>
</ol>
<p>Valid questions are imported even if some fail; the others are listed so you can fix them. The format is one <code>##</code> per question, with options as <code>- [ ]</code> and the correct one as <code>- [x]</code>. An optional <code>points: 1</code> follows the last option.</p>
</details>
<details><summary>Cover image</summary>
<p><b>Generate image prompt</b>, in the path's details, composes a prompt from the title and description for an image tool of your choice. You then upload the image yourself. Without one, the catalog shows a coloured card with the initial.</p>
</details>
<details><summary>The two chats</summary>
<p><b>Discussion</b> is for enrolled people, and opens once a path is published. <b>Formatori notes</b> is only for formators, Coordinators and Admins, and works from the draft stage: enrolled people never see it.</p>
</details>
<details><summary>Co-authors</summary>
<p>In the path, the owner searches for other Formation members and adds them. Co-authors edit the path together with the owner.</p>
</details>
<details><summary>Certificates and enrollment</summary>
<p>The certificate appears by itself when someone has passed every module quiz and the final exam. Press <b>Who?</b> to see who is enrolled.</p>
</details>
<p><a class="btn" href="#" data-tab="formation">Open Formation Paths</a></p>$help_guide$, 120, now(), 'migration 116');

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, updated_at, updated_by_email)
values ('build-path_it', 'build-path', 'it', null, 'Costruire un percorso', 'Moduli, capitoli, quiz, pubblicazione', 'check', array['dept:FORM', 'coordinator'], $help_guide$<p class="lead">I membri di Formazione costruiscono i percorsi, preferibilmente insieme. Un percorso ha un proprietario e un numero qualsiasi di coautori.</p>
<h2>I passi</h2>
<ol>
<li><b>Crealo.</b> <b>Formation Paths → + New path</b>: titolo, descrizione, destinatari, tipo di sessione e, se servono, date del corso e scadenza delle iscrizioni. Nasce come bozza: lo vedono solo chi lo costruisce, gli altri formatori, i Coordinatori e gli Admin.</li>
<li><b>Costruisci la struttura.</b> <b>+ Add module</b>, poi <b>+ Chapter</b>, poi i post. Le frecce cambiano l'ordine.</li>
<li><b>Inserisci i testi dell'archivio.</b> Apri un documento e premi <b>+ Path</b>. Da lì puoi anche creare un modulo e un capitolo.</li>
<li><b>Aggiungi i quiz.</b> Uno per modulo, e un esame finale se lo vuoi, ciascuno con una soglia di superamento.</li>
<li><b>Pubblica.</b> <b>Publish</b> lo apre a tutti. Puoi continuare ad aggiungere dopo.</li>
</ol>
<div class="note"><b>Delete</b> su un modulo, un capitolo o un percorso non si può annullare, e un percorso cancellato porta via iscrizioni e certificati. Per togliere un percorso dal catalogo usa <b>Archive</b>: i certificati già ottenuti restano.</div>
<details><summary>Scrivere un quiz con uno strumento AI</summary>
<ol>
<li>Nel quiz, premi <b>Copy AI prompt</b>.</li>
<li>Incollalo in uno strumento AI con il testo del modulo.</li>
<li>Leggi il risultato, che è solo una bozza, poi incollalo in <b>Import quiz from Markdown</b>.</li>
</ol>
<p>Le domande valide vengono importate anche se alcune falliscono; le altre sono elencate per correggerle. Il formato è un <code>##</code> per domanda, con le opzioni come <code>- [ ]</code> e quella giusta come <code>- [x]</code>. Dopo l'ultima opzione può seguire <code>points: 1</code>.</p>
</details>
<details><summary>Immagine di copertina</summary>
<p><b>Generate image prompt</b>, nei dettagli del percorso, compone un prompt da titolo e descrizione per uno strumento di immagini a tua scelta. Poi carichi tu l'immagine. Senza, il catalogo mostra una scheda colorata con l'iniziale.</p>
</details>
<details><summary>Le due chat</summary>
<p><b>Discussion</b> è per gli iscritti e si apre quando un percorso è pubblicato. <b>Formatori notes</b> è solo per formatori, Coordinatori e Admin, e funziona già dalla bozza: gli iscritti non la vedono mai.</p>
</details>
<details><summary>Coautori</summary>
<p>Nel percorso, il proprietario cerca altri membri di Formazione e li aggiunge. I coautori modificano il percorso insieme al proprietario.</p>
</details>
<details><summary>Certificati e iscrizioni</summary>
<p>Il certificato compare da solo quando qualcuno ha superato tutti i quiz dei moduli e l'esame finale. Premi <b>Who?</b> per vedere chi è iscritto.</p>
</details>
<p><a class="btn" href="#" data-tab="formation">Apri Formation Paths</a></p>$help_guide$, 120, now(), 'migration 116');

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, updated_at, updated_by_email)
values ('teamwork_en', 'teamwork', 'en', null, 'Working as a team', 'How departments fit together', 'role', array['operator', 'dept:*'], $help_guide$<p class="lead">We are a team spread across several cities, most of us working a little at a time on a phone. These rules let us work together without anyone having to carry everything.</p>
<h2>How it fits together</h2>
<ul>
<li><b>The material:</b> Formation builds the paths and brings in texts. Coordination runs the work on them.</li>
<li><b>The people:</b> HR welcomes and follows those who work. Reward looks after credits and compensation.</li>
<li><b>Communication</b> works with both, so that people know what exists and feel welcome.</li>
<li><b>Archive &amp; Data</b> keeps the archive's records correct.</li>
</ul>
<h2>Five rules</h2>
<ol>
<li><b>Whoever proposes does not approve.</b> Nobody alone admits a person, gives them work and decides what they are paid. During development Admins are the exception, and everything they do is recorded.</li>
<li><b>Every decision about a person has a written reason.</b> A decision without one isn't valid.</li>
<li><b>Everything leaves a trace.</b> Changes to the archive are logged by the database, and nobody can alter the log. It records who changes things, never who reads them.</li>
<li><b>Silence isn't approval.</b> A proposal for a decision about people or policy with no answer after 7 days goes to the Owner.</li>
<li><b>Say it early.</b> Giving up a task costs nothing; disappearing can cost reputation. The same holds for everyone: if you can't manage something, tell your lead.</li>
</ol>
<h2>Where to talk</h2>
<table><tr><th>What</th><th>Where</th></tr>
<tr><td>Your department's daily work</td><td><b>My Department → Team channel</b>, private to the department</td></tr>
<tr><td>What the department is focused on</td><td>The status and <b>Priorities</b> at the top of its page</td></tr>
<tr><td>A problem with a document or the app</td><td><b>Report a Problem or Suggestion</b>, or <b>Messages</b> if you are a Coordinator</td></tr>
<tr><td>An experience, a difficulty, an idea</td><td><b>Share with us</b></td></tr>
<tr><td>Something for a group of members</td><td><b>Boards</b></td></tr></table>
<details><summary>A department with one person</summary>
<p>A department is a set of responsibilities, not an office. One person can belong to several, and a department with one member is still a department. The structure is ready for when people arrive.</p>
</details>
<details><summary>Working in unity</summary>
<p>These tools serve people. A note in a queue is a colleague's work: write as you would speak to them. When a review is hard to give, or a decision weighs on someone, a call is often better than a message.</p>
</details>
<p><a href="#" data-help-guide="who-does-what">See who can do what</a></p>$help_guide$, 130, now(), 'migration 116');

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, updated_at, updated_by_email)
values ('teamwork_it', 'teamwork', 'it', null, 'Lavorare in team', 'Come i reparti stanno insieme', 'role', array['operator', 'dept:*'], $help_guide$<p class="lead">Siamo un team sparso in più città, e la maggior parte di noi lavora un po' alla volta dal telefono. Queste regole ci fanno lavorare insieme senza che nessuno debba portare tutto.</p>
<h2>Come sta insieme</h2>
<ul>
<li><b>Il materiale:</b> Formazione costruisce i percorsi e porta i testi. Coordinamento guida il lavoro su di essi.</li>
<li><b>Le persone:</b> HR accoglie e segue chi lavora. Reward si occupa di crediti e compensi.</li>
<li><b>Communication</b> lavora con entrambi, perché le persone sappiano che cosa esiste e si sentano accolte.</li>
<li><b>Archive &amp; Data</b> tiene corretti i record dell'archivio.</li>
</ul>
<h2>Cinque regole</h2>
<ol>
<li><b>Chi propone non approva.</b> Nessuno da solo ammette una persona, le dà lavoro e decide quanto è pagata. Durante lo sviluppo gli Admin sono l'eccezione, e tutto ciò che fanno è registrato.</li>
<li><b>Ogni decisione su una persona ha un motivo scritto.</b> Senza, non è valida.</li>
<li><b>Tutto lascia traccia.</b> Le modifiche all'archivio le registra il database, e nessuno può alterare il registro. Registra chi modifica, mai chi legge.</li>
<li><b>Il silenzio non è approvazione.</b> Una proposta su persone o regole senza risposta dopo 7 giorni va all'Owner.</li>
<li><b>Dillo presto.</b> Rinunciare a un task non costa nulla; sparire può costare reputazione. Vale per tutti: se non ce la fai, dillo al tuo responsabile.</li>
</ol>
<h2>Dove parlare</h2>
<table><tr><th>Che cosa</th><th>Dove</th></tr>
<tr><td>Il lavoro quotidiano del reparto</td><td><b>My Department → Team channel</b>, privato per il reparto</td></tr>
<tr><td>Su che cosa è concentrato il reparto</td><td>Lo stato e le <b>Priorities</b> in cima alla sua pagina</td></tr>
<tr><td>Un problema con un documento o con l'app</td><td><b>Report a Problem or Suggestion</b>, o <b>Messages</b> se sei Coordinatore</td></tr>
<tr><td>Un'esperienza, una difficoltà, un'idea</td><td><b>Share with us</b></td></tr>
<tr><td>Qualcosa per un gruppo di membri</td><td><b>Boards</b></td></tr></table>
<details><summary>Un reparto con una sola persona</summary>
<p>Un reparto è un insieme di responsabilità, non un ufficio. Una persona può far parte di più reparti, e un reparto con un solo membro resta un reparto. La struttura è pronta per quando arriveranno le persone.</p>
</details>
<details><summary>Lavorare in unità</summary>
<p>Questi strumenti servono le persone. Una nota in una coda è il lavoro di un collega: scrivi come gli parleresti. Quando una revisione è difficile da dare, o una decisione pesa su qualcuno, spesso una telefonata è meglio di un messaggio.</p>
</details>
<p><a href="#" data-help-guide="who-does-what">Vedi chi può fare cosa</a></p>$help_guide$, 130, now(), 'migration 116');

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, updated_at, updated_by_email)
values ('role-lead_en', 'role-lead', 'en', null, 'Leading a department', 'Welcome: your tasks and rhythm', 'role', array['lead'], $help_guide$<p class="lead">Welcome. As a lead you are accountable for your department's decisions, and you keep its members aligned and encouraged. You don't have to do all the work yourself.</p>
<h2>What is yours</h2>
<ul>
<li><b>Your department's field:</b> read its guide below.</li>
<li><b>The status and priorities</b> members see at the top of the page.</li>
<li><b>The Team channel:</b> you can pin what matters.</li>
<li><b>Your members:</b> you can remove someone from the department. Only an Admin adds members and appoints leads.</li>
<li><b>Your department's rules:</b> you can propose a change with <b>Propose change</b> in Policy, if the department owns that rule. An Admin who isn't the proposer applies it, after the team has reviewed it.</li>
<li><b>Share with us:</b> every lead reads what people share, and each can thank and reply.</li>
</ul>
<h2>What isn't yours</h2>
<p>A lead doesn't decide alone about a person's pay, admission or exclusion: those decisions follow <a href="#" data-help-guide="who-does-what">their own steps</a>. The Owner appoints leads.</p>
<h2>A suggested rhythm</h2>
<p>These are suggestions, not rules. Adapt them with your team.</p>
<h3>Every day, a few minutes</h3>
<ul>
<li>Read the <b>Team channel</b> and answer what waits on you.</li>
<li>Look at <b>Share with us</b>: nobody who shares should go unheard.</li>
<li>Check your department's own queue (its guide says which).</li>
</ul>
<h3>Every week</h3>
<ul>
<li><b>Update status</b> honestly, with a short note. The app may suggest a status: you decide, and it is only a hint.</li>
<li>Tick off done <b>Priorities</b> and add the next ones. Keep the list short.</li>
<li>Write one message of thanks or encouragement to the team.</li>
<li>Look for proposals or decisions that have waited close to 7 days.</li>
</ul>
<h3>When something changes</h3>
<ul>
<li>Someone new joins: welcome them in the channel and give them a first small step.</li>
<li>Someone goes quiet: ask how they are before asking about the work.</li>
<li>A problem is about a person, not one piece of work: bring it to HR.</li>
</ul>
<details><summary>What the status means</summary>
<p><b>On track</b>, <b>Slowing down</b>, <b>Stalled</b>. It is your honest judgement, not a measurement: the note matters more than the colour. Admins see all departments together in <b>Project overview</b>. "Stalled" is a request for help, not a failure.</p>
</details>
<details><summary>Your department's guide</summary>
<ul>
<li><a href="#" data-help-guide="my-department">The sections every department has</a></li>
<li><a href="#" data-help-guide="dept-hr">HR</a></li>
<li><a href="#" data-help-guide="dept-coordination">Coordination</a></li>
<li><a href="#" data-help-guide="dept-formation">Formation</a></li>
<li><a href="#" data-help-guide="dept-reward">Reward</a></li>
<li><a href="#" data-help-guide="dept-communication">Communication</a></li>
<li><a href="#" data-help-guide="dept-archive">Archive &amp; Data</a></li>
</ul>
</details>
<p><a class="btn" href="#" data-tab="mydepartment">Open My Department</a></p>$help_guide$, 140, now(), 'migration 116');

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, updated_at, updated_by_email)
values ('role-lead_it', 'role-lead', 'it', null, 'Guidare un reparto', 'Benvenuto: compiti e ritmo', 'role', array['lead'], $help_guide$<p class="lead">Benvenuto. Come responsabile rispondi delle decisioni del tuo reparto, e tieni i suoi membri allineati e incoraggiati. Non devi fare tutto il lavoro da solo.</p>
<h2>Che cosa è tuo</h2>
<ul>
<li><b>Il campo del tuo reparto:</b> leggi la sua guida qui sotto.</li>
<li><b>Lo stato e le priorità</b> che i membri vedono in cima alla pagina.</li>
<li><b>Il Team channel:</b> puoi fissare ciò che conta.</li>
<li><b>I tuoi membri:</b> puoi togliere qualcuno dal reparto. Solo un Admin aggiunge membri e nomina i responsabili.</li>
<li><b>Le regole del tuo reparto:</b> puoi proporre una modifica con <b>Propose change</b> in Policy, se la regola è del reparto. La applica un Admin diverso da chi propone, dopo che il team l'ha esaminata.</li>
<li><b>Share with us:</b> ogni responsabile legge ciò che le persone condividono, e ciascuno può ringraziare e rispondere.</li>
</ul>
<h2>Che cosa non è tuo</h2>
<p>Un responsabile non decide da solo su compenso, ammissione o esclusione di una persona: queste decisioni seguono <a href="#" data-help-guide="who-does-what">i loro passi</a>. I responsabili li nomina l'Owner.</p>
<h2>Un ritmo suggerito</h2>
<p>Sono suggerimenti, non regole. Adattali con il tuo team.</p>
<h3>Ogni giorno, pochi minuti</h3>
<ul>
<li>Leggi il <b>Team channel</b> e rispondi a ciò che aspetta te.</li>
<li>Guarda <b>Share with us</b>: nessuno che condivide deve restare senza ascolto.</li>
<li>Controlla la coda propria del reparto (la sua guida dice quale).</li>
</ul>
<h3>Ogni settimana</h3>
<ul>
<li><b>Update status</b> con onestà, con una breve nota. L'app può suggerire uno stato: decidi tu, è solo un'indicazione.</li>
<li>Spunta le <b>Priorities</b> fatte e aggiungi le prossime. Tieni la lista corta.</li>
<li>Scrivi al team un messaggio di ringraziamento o di incoraggiamento.</li>
<li>Cerca proposte o decisioni in attesa da quasi 7 giorni.</li>
</ul>
<h3>Quando qualcosa cambia</h3>
<ul>
<li>Arriva una persona nuova: accoglila nel canale e dalle un primo piccolo passo.</li>
<li>Qualcuno si fa silenzioso: chiedi come sta, prima di chiedere del lavoro.</li>
<li>Un problema riguarda una persona, non un singolo lavoro: portalo a HR.</li>
</ul>
<details><summary>Che cosa significa lo stato</summary>
<p><b>On track</b>, <b>Slowing down</b>, <b>Stalled</b>. È il tuo giudizio onesto, non una misura: la nota conta più del colore. Gli Admin vedono tutti i reparti insieme in <b>Project overview</b>. "Stalled" è una richiesta di aiuto, non un fallimento.</p>
</details>
<details><summary>La guida del tuo reparto</summary>
<ul>
<li><a href="#" data-help-guide="my-department">Le sezioni che ogni reparto ha</a></li>
<li><a href="#" data-help-guide="dept-hr">HR</a></li>
<li><a href="#" data-help-guide="dept-coordination">Coordinamento</a></li>
<li><a href="#" data-help-guide="dept-formation">Formazione</a></li>
<li><a href="#" data-help-guide="dept-reward">Reward</a></li>
<li><a href="#" data-help-guide="dept-communication">Communication</a></li>
<li><a href="#" data-help-guide="dept-archive">Archive &amp; Data</a></li>
</ul>
</details>
<p><a class="btn" href="#" data-tab="mydepartment">Apri My Department</a></p>$help_guide$, 140, now(), 'migration 116');

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, updated_at, updated_by_email)
values ('role-coordinator_en', 'role-coordinator', 'en', null, 'Being a Coordinator', 'Welcome: your tasks and rhythm', 'role', array['coordinator'], $help_guide$<p class="lead">Welcome. A Coordinator keeps the flow of work orderly: what needs doing, who is doing it, and what has stopped.</p>
<h2>Your field</h2>
<ul>
<li><b>Tasks:</b> create them, assign them or leave them open, reassign what is stuck.</li>
<li><b>Reviews:</b> you can give verdicts on tasks and decide on proposals and readings, never your own.</li>
<li><b>Messages:</b> reports from everyone reach you. Answer them, or turn them into a task.</li>
<li><b>The archive's order:</b> you can edit a document's details, set the preferred version, see its <b>Change history</b>, and link the pieces of a month's Word of Life.</li>
<li><b>Boards:</b> you can post anywhere, pin, and name each board's editors.</li>
</ul>
<h2>What isn't yours</h2>
<ul>
<li>Publishing a reviewed task and paying its credits: an Admin decides.</li>
<li>Admitting people: HR and Admin. If a person's behaviour is the problem, not one task, bring it to HR.</li>
<li>Deciding what work is worth: the rates are Reward's. Extra credits above the threshold need the Coordination lead.</li>
<li>Your own proposals: they pass through review like everyone else's.</li>
</ul>
<h2>A suggested rhythm</h2>
<p>These are suggestions, not rules.</p>
<h3>Every day</h3>
<ul>
<li><b>Messages:</b> reply, or use <b>Create task</b>.</li>
<li><b>Proposals → To review:</b> the oldest first. The tab shows a count.</li>
<li><b>Tasks → Review Tasks:</b> whatever is waiting, if no Revisor has taken it.</li>
<li><b>Read aloud → To listen,</b> if no one with that qualification is on it.</li>
</ul>
<h3>Every week</h3>
<ul>
<li><b>Tasks → Team overview,</b> with <b>Overdue only</b>: contact whoever is late, before taking anything back.</li>
<li><b>Tasks Store:</b> is there enough open work, and is it clear enough to take?</li>
<li><b>Proposals → Word of Life:</b> what is missing for the coming month? Open a translation task early.</li>
<li>Anything overdue past 7 days: find out why it is stuck.</li>
</ul>
<details><summary>Free up: use it last</summary>
<p><b>Free up (back to open)</b> lowers the person's reputation and needs a reason. First ask. If they honestly give up, there is no penalty. <b>Reassign</b> moves a task with no penalty either.</p>
</details>
<p><a href="#" data-help-guide="coordinate-team">How to create and follow tasks</a></p>
<p><a class="btn" href="#" data-tab="tasks">Open Tasks</a></p>$help_guide$, 150, now(), 'migration 116');

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, updated_at, updated_by_email)
values ('role-coordinator_it', 'role-coordinator', 'it', null, 'Essere Coordinatore', 'Benvenuto: compiti e ritmo', 'role', array['coordinator'], $help_guide$<p class="lead">Benvenuto. Un Coordinatore tiene ordinato il flusso di lavoro: che cosa va fatto, chi lo sta facendo, e che cosa si è fermato.</p>
<h2>Il tuo campo</h2>
<ul>
<li><b>Task:</b> crearli, assegnarli o lasciarli aperti, riassegnare ciò che è fermo.</li>
<li><b>Revisioni:</b> puoi dare verdetti sui task e decidere su proposte e letture, mai sulle tue.</li>
<li><b>Messages:</b> le segnalazioni di tutti arrivano a te. Rispondi, o trasformale in un task.</li>
<li><b>L'ordine dell'archivio:</b> puoi modificare i dati di un documento, scegliere la versione preferita, vedere la sua <b>Change history</b> e collegare i pezzi della Parola di Vita del mese.</li>
<li><b>Bacheche:</b> puoi pubblicare ovunque, fissare i post e nominare chi cura ogni bacheca.</li>
</ul>
<h2>Che cosa non è tuo</h2>
<ul>
<li>Chiudere un task rivisto e pagarne i crediti: decide un Admin.</li>
<li>Ammettere persone: HR e Admin. Se il problema è il comportamento di una persona, non un task, portalo a HR.</li>
<li>Decidere quanto vale il lavoro: le tariffe sono di Reward. I crediti extra sopra la soglia richiedono il responsabile di Coordinamento.</li>
<li>Le tue proposte: passano dalla revisione come quelle di tutti.</li>
</ul>
<h2>Un ritmo suggerito</h2>
<p>Sono suggerimenti, non regole.</p>
<h3>Ogni giorno</h3>
<ul>
<li><b>Messages:</b> rispondi, o usa <b>Create task</b>.</li>
<li><b>Proposals → To review:</b> prima le più vecchie. La scheda mostra un contatore.</li>
<li><b>Tasks → Review Tasks:</b> ciò che aspetta, se nessun Revisore l'ha preso.</li>
<li><b>Read aloud → To listen,</b> se nessuno con quella qualifica se ne occupa.</li>
</ul>
<h3>Ogni settimana</h3>
<ul>
<li><b>Tasks → Team overview,</b> con <b>Overdue only</b>: contatta chi è in ritardo, prima di riprendere qualcosa.</li>
<li><b>Tasks Store:</b> c'è abbastanza lavoro aperto, ed è abbastanza chiaro da prendere?</li>
<li><b>Proposals → Word of Life:</b> che cosa manca per il mese prossimo? Apri presto un task di traduzione.</li>
<li>Ciò che è in ritardo oltre i 7 giorni: scopri perché è fermo.</li>
</ul>
<details><summary>Free up: da usare per ultimo</summary>
<p><b>Free up (back to open)</b> abbassa la reputazione della persona e richiede un motivo. Prima chiedi. Se rinuncia onestamente non c'è penalità. Neanche <b>Reassign</b> comporta penalità.</p>
</details>
<p><a href="#" data-help-guide="coordinate-team">Come creare e seguire i task</a></p>
<p><a class="btn" href="#" data-tab="tasks">Apri Tasks</a></p>$help_guide$, 150, now(), 'migration 116');

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, updated_at, updated_by_email)
values ('role-formator_en', 'role-formator', 'en', null, 'Being a formator', 'Welcome: your tasks and rhythm', 'role', array['dept:FORM'], $help_guide$<p class="lead">Welcome. Formators build the formation paths on the archive's material and accompany those who follow them. In the app, a formator is a member of the Formation department.</p>
<h2>Your field</h2>
<ul>
<li><b>Paths:</b> design them, preferably together, with an owner and co-authors.</li>
<li><b>People on a path:</b> answer in the <b>Discussion</b>, follow enrollments.</li>
<li><b>Quizzes:</b> draft them with an AI tool, read them, and import them.</li>
<li><b>Boards:</b> if you are named editor of a board, you look after it.</li>
<li><b>Reserved documents:</b> you can propose them, give or remove the reserved level, and enable people to read them.</li>
<li><b>Reviewing:</b> you can decide on proposals, and another formator's reserved ones.</li>
</ul>
<h2>What isn't yours</h2>
<ul>
<li>A shortcut into the archive: a formator's text passes through review like everyone else's.</li>
<li>Deciding penalties alone: an editor proposes them, and the Formation lead or the HR lead approves.</li>
</ul>
<div class="note"><b>Reserved has a limit.</b> It decides what the app shows. PDFs and InPage files stay in the Drive folder, open to anyone with the link. For a very delicate document, keep only the text in the archive and don't upload the PDF.</div>
<h2>A suggested rhythm</h2>
<p>These are suggestions, not rules.</p>
<h3>Every day or two</h3>
<ul>
<li>Answer the <b>Discussion</b> on your paths.</li>
<li>If you edit a board, look at the posts waiting.</li>
<li>Read the department's <b>Team channel</b>.</li>
</ul>
<h3>Every week</h3>
<ul>
<li>Move one path forward: a chapter, a quiz, a correction.</li>
<li>Use <b>Formatori notes</b> to ask for and give advice on each other's paths.</li>
<li>Look at <b>Proposals → To review</b>, reserved ones especially, since only you and Admins can decide them.</li>
</ul>
<h3>Every month</h3>
<ul>
<li>With your lead, look at the <b>Formation pipeline</b>: what is in draft, what is published.</li>
<li>Check who is enabled for reserved documents, and whether they still need it.</li>
</ul>
<p><a href="#" data-help-guide="build-path">How to build a path</a> · <a href="#" data-help-guide="dept-formation">The Formation page</a> · <a href="#" data-help-guide="moderate-board">Looking after a board</a></p>
<p><a class="btn" href="#" data-tab="formation">Open Formation Paths</a></p>$help_guide$, 160, now(), 'migration 116');

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, updated_at, updated_by_email)
values ('role-formator_it', 'role-formator', 'it', null, 'Essere formatore', 'Benvenuto: compiti e ritmo', 'role', array['dept:FORM'], $help_guide$<p class="lead">Benvenuto. I formatori costruiscono i percorsi formativi sul materiale dell'archivio e accompagnano chi li segue. Nell'app, formatore è chi fa parte del reparto Formazione.</p>
<h2>Il tuo campo</h2>
<ul>
<li><b>Percorsi:</b> progettarli, preferibilmente insieme, con un proprietario e dei coautori.</li>
<li><b>Le persone di un percorso:</b> rispondere nella <b>Discussion</b>, seguire le iscrizioni.</li>
<li><b>Quiz:</b> abbozzarli con uno strumento AI, rileggerli e importarli.</li>
<li><b>Bacheche:</b> se sei nominato per una bacheca, la curi.</li>
<li><b>Documenti riservati:</b> puoi proporli, dare o togliere il livello riservato e abilitare persone a leggerli.</li>
<li><b>Revisioni:</b> puoi decidere sulle proposte, e su quelle riservate di un altro formatore.</li>
</ul>
<h2>Che cosa non è tuo</h2>
<ul>
<li>Una scorciatoia verso l'archivio: il testo di un formatore passa dalla revisione come quelli di tutti.</li>
<li>Decidere penalità da solo: chi cura una bacheca le propone, e le approva il responsabile di Formazione o di HR.</li>
</ul>
<div class="note"><b>Riservato ha un limite.</b> Decide che cosa mostra l'app. PDF e file InPage restano nella cartella Drive, aperta a chi ha il link. Per un documento molto delicato, tieni in archivio solo il testo e non caricare il PDF.</div>
<h2>Un ritmo suggerito</h2>
<p>Sono suggerimenti, non regole.</p>
<h3>Ogni uno o due giorni</h3>
<ul>
<li>Rispondi nella <b>Discussion</b> dei tuoi percorsi.</li>
<li>Se curi una bacheca, guarda i post in attesa.</li>
<li>Leggi il <b>Team channel</b> del reparto.</li>
</ul>
<h3>Ogni settimana</h3>
<ul>
<li>Fai avanzare un percorso: un capitolo, un quiz, una correzione.</li>
<li>Usa <b>Formatori notes</b> per chiedere e dare consigli sui percorsi degli altri.</li>
<li>Guarda <b>Proposals → To review</b>, soprattutto le riservate, che possono decidere solo i formatori e gli Admin.</li>
</ul>
<h3>Ogni mese</h3>
<ul>
<li>Con il responsabile, guarda la <b>Formation pipeline</b>: che cosa è in bozza, che cosa è pubblicato.</li>
<li>Controlla chi è abilitato ai riservati, e se ne ha ancora bisogno.</li>
</ul>
<p><a href="#" data-help-guide="build-path">Come costruire un percorso</a> · <a href="#" data-help-guide="dept-formation">La pagina di Formazione</a> · <a href="#" data-help-guide="moderate-board">Curare una bacheca</a></p>
<p><a class="btn" href="#" data-tab="formation">Apri Formation Paths</a></p>$help_guide$, 160, now(), 'migration 116');

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, updated_at, updated_by_email)
values ('role-admin_en', 'role-admin', 'en', null, 'Being an Admin', 'Welcome: your tasks and rhythm', 'role', array['admin'], $help_guide$<p class="lead">Welcome. Admin is a technical role, not a governing one. It means you can change configuration and data; decisions about people, work and money belong to the departments. You carry them out and keep the system running.</p>
<div class="note"><b>During development</b> an Admin may do everything without approval, own work included, and every action is recorded. Compensation runs keep a second person, because they concern money. This will be reviewed when Revisors are working in the app.</div>
<h2>Only you can</h2>
<ul>
<li>Change roles, and apply qualifications and people decisions.</li>
<li>Close reviewed tasks with <b>Publish</b> or <b>Reject</b>, and publish the final document.</li>
<li>Add visible documents directly (<b>+ New document</b>, Bulk Import, Hayat Extract), and delete or restore them.</li>
<li>Copy PDFs to Drive after approval.</li>
<li>Decide policy proposals and compensation runs you didn't prepare.</li>
<li>Publish <b>Announcements</b>, edit lists in <b>Options</b>, and edit these guides.</li>
</ul>
<h2>A suggested rhythm</h2>
<p>These are suggestions, not rules. The Admins may share them out.</p>
<h3>Every day</h3>
<ul>
<li><b>Tasks → Publish Tasks:</b> what Revisors have approved waits only on you.</li>
<li><b>Proposals → Files for Drive:</b> nothing should stay behind. The storage plan is small, and the copy in Supabase is removed once on Drive.</li>
<li><b>Messages</b>, and <b>Share with us</b>.</li>
</ul>
<h3>Every week</h3>
<ul>
<li><b>Project overview:</b> read every department's status and note. A "Stalled" is a call to talk to that lead.</li>
<li><b>My Department → HR → Pending decisions,</b> and <b>Options → Policy</b>: nothing should wait beyond 7 days.</li>
<li><b>Tasks → Documents ready to publish.</b></li>
<li><b>Read aloud → Readers → Space:</b> how much is used, and the list of files to erase.</li>
</ul>
<h3>When needed</h3>
<ul>
<li>A release: announce it through <b>Announcements</b>, with Communication.</li>
<li>Someone asks to withdraw consent for their readings and can't do it themselves.</li>
<li>A department needs a new member or lead (the Owner appoints leads).</li>
</ul>
<details><summary>Testing as Admin</summary>
<p>What works for you proves nothing about what others can do: your role passes every block. Test other roles with test accounts. Tasks you approve yourself are recognisable, so Reward's reports can leave out test credits.</p>
</details>
<p><a href="#" data-help-guide="administer">How to do each of these</a></p>$help_guide$, 170, now(), 'migration 116');

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, updated_at, updated_by_email)
values ('role-admin_it', 'role-admin', 'it', null, 'Essere Admin', 'Benvenuto: compiti e ritmo', 'role', array['admin'], $help_guide$<p class="lead">Benvenuto. Admin è un ruolo tecnico, non di governo. Significa che puoi cambiare configurazione e dati; le decisioni su persone, lavoro e denaro spettano ai reparti. Tu le esegui e tieni in funzione il sistema.</p>
<div class="note"><b>Durante lo sviluppo</b> un Admin può fare tutto senza approvazioni, anche sul proprio lavoro, e ogni azione è registrata. I compensi mantengono una seconda persona, perché riguardano denaro. Si rivedrà quando i Revisori lavoreranno nell'app.</div>
<h2>Solo tu puoi</h2>
<ul>
<li>Cambiare i ruoli, e applicare qualifiche e decisioni sulle persone.</li>
<li>Chiudere i task rivisti con <b>Publish</b> o <b>Reject</b>, e pubblicare il documento finale.</li>
<li>Aggiungere direttamente documenti visibili (<b>+ New document</b>, Bulk Import, Hayat Extract), e cancellarli o ripristinarli.</li>
<li>Copiare i PDF su Drive dopo l'approvazione.</li>
<li>Decidere proposte di regole e compensi che non hai preparato tu.</li>
<li>Pubblicare <b>Announcements</b>, modificare gli elenchi in <b>Options</b> e queste guide.</li>
</ul>
<h2>Un ritmo suggerito</h2>
<p>Sono suggerimenti, non regole. Gli Admin possono dividerseli.</p>
<h3>Ogni giorno</h3>
<ul>
<li><b>Tasks → Publish Tasks:</b> ciò che i Revisori hanno approvato aspetta solo te.</li>
<li><b>Proposals → Files for Drive:</b> nulla deve restare indietro. Il piano di spazio è piccolo, e la copia su Supabase si toglie una volta su Drive.</li>
<li><b>Messages</b> e <b>Share with us</b>.</li>
</ul>
<h3>Ogni settimana</h3>
<ul>
<li><b>Project overview:</b> leggi stato e nota di ogni reparto. Uno "Stalled" è un invito a parlare con quel responsabile.</li>
<li><b>My Department → HR → Pending decisions,</b> e <b>Options → Policy</b>: nulla deve aspettare oltre 7 giorni.</li>
<li><b>Tasks → Documents ready to publish.</b></li>
<li><b>Read aloud → Readers → Space:</b> quanto è usato, e l'elenco dei file da cancellare.</li>
</ul>
<h3>Quando serve</h3>
<ul>
<li>Una nuova versione: annunciala con <b>Announcements</b>, insieme a Communication.</li>
<li>Qualcuno chiede di ritirare il consenso per le sue letture e non può farlo da solo.</li>
<li>Un reparto ha bisogno di un nuovo membro o responsabile (i responsabili li nomina l'Owner).</li>
</ul>
<details><summary>Provare da Admin</summary>
<p>Ciò che funziona per te non prova nulla su ciò che possono fare gli altri: il tuo ruolo supera ogni blocco. Prova gli altri ruoli con account di prova. I task che ti approvi da solo sono riconoscibili, così i report di Reward possono escludere i crediti di prova.</p>
</details>
<p><a href="#" data-help-guide="administer">Come fare ciascuna di queste cose</a></p>$help_guide$, 170, now(), 'migration 116');

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, updated_at, updated_by_email)
values ('my-department_en', 'my-department', 'en', null, 'My Department: the common sections', 'What every department page has', 'dept', array['dept:*'], $help_guide$<p class="lead"><b>My Department</b> is your team's own page. Every department has the same sections, and then its own tools. If you belong to several, choose from the list at the top.</p>
<h2>In order, from the top</h2>
<table><tr><th>Section</th><th>What it is</th><th>Who can change it</th></tr>
<tr><td><b>Status</b></td><td>On track, Slowing down or Stalled, with the lead's note. The app may add a hint under "Data suggests", which is never applied by itself</td><td>The lead or Admin</td></tr>
<tr><td><b>Priorities</b></td><td>A short list of what the team is focused on, with dates if useful. It isn't a second task system: no assignee and no credits</td><td>The lead or Admin</td></tr>
<tr><td><b>Team</b></td><td>The members and the lead</td><td>The lead or Admin can remove a member. Admin adds members and appoints leads, in Options</td></tr>
<tr><td><b>Team channel</b></td><td>A private conversation for the department, with images. Nobody outside it sees it, except Admins</td><td>Any member writes. Your own message can be changed for 15 minutes. The lead or Admin pins</td></tr>
<tr><td>The department's own tools</td><td>See its guide</td><td>Depends on the tool</td></tr>
<tr><td><b>Policy</b></td><td>The rules and values in force, and the history of every proposal</td><td>The owning department's lead proposes, and an Admin who isn't the proposer decides</td></tr></table>
<details><summary>The tools of each department</summary>
<ul>
<li><a href="#" data-help-guide="dept-hr">HR</a>: Team Applications, People, Pending decisions</li>
<li><a href="#" data-help-guide="dept-coordination">Coordination</a>: Extra credits, Task flow</li>
<li><a href="#" data-help-guide="dept-formation">Formation</a>: Formation pipeline, Access to reserved documents</li>
<li><a href="#" data-help-guide="dept-reward">Reward</a>: Credits in circulation, Compensation runs, Anomaly report</li>
<li><a href="#" data-help-guide="dept-communication">Communication</a>: Start Here cards</li>
<li><a href="#" data-help-guide="dept-archive">Archive &amp; Data</a>: Archive tools, Deleted documents, Translation prompt</li>
</ul>
</details>
<p><a class="btn" href="#" data-tab="mydepartment">Open My Department</a></p>$help_guide$, 180, now(), 'migration 116');

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, updated_at, updated_by_email)
values ('my-department_it', 'my-department', 'it', null, 'My Department: le sezioni comuni', 'Che cosa ha ogni pagina di reparto', 'dept', array['dept:*'], $help_guide$<p class="lead"><b>My Department</b> è la pagina del tuo team. Ogni reparto ha le stesse sezioni, e poi i suoi strumenti. Se fai parte di più reparti, scegli dall'elenco in alto.</p>
<h2>In ordine, dall'alto</h2>
<table><tr><th>Sezione</th><th>Che cos'è</th><th>Chi può cambiarla</th></tr>
<tr><td><b>Stato</b></td><td>On track, Slowing down o Stalled, con la nota del responsabile. L'app può aggiungere un'indicazione sotto "Data suggests", che non si applica mai da sola</td><td>Il responsabile o un Admin</td></tr>
<tr><td><b>Priorities</b></td><td>Una lista corta di ciò su cui il team è concentrato, con date se utili. Non è un secondo sistema di task: niente assegnatario e niente crediti</td><td>Il responsabile o un Admin</td></tr>
<tr><td><b>Team</b></td><td>I membri e il responsabile</td><td>Il responsabile o un Admin può togliere un membro. Un Admin aggiunge i membri e nomina i responsabili, in Options</td></tr>
<tr><td><b>Team channel</b></td><td>Una conversazione privata del reparto, con immagini. Da fuori non la vede nessuno, tranne gli Admin</td><td>Ogni membro scrive. Il tuo messaggio si può cambiare per 15 minuti. Il responsabile o un Admin fissa</td></tr>
<tr><td>Gli strumenti del reparto</td><td>Vedi la sua guida</td><td>Dipende dallo strumento</td></tr>
<tr><td><b>Policy</b></td><td>Le regole e i valori in vigore, e la storia di ogni proposta</td><td>Propone il responsabile del reparto competente, decide un Admin diverso da chi propone</td></tr></table>
<details><summary>Gli strumenti di ogni reparto</summary>
<ul>
<li><a href="#" data-help-guide="dept-hr">HR</a>: Team Applications, People, Pending decisions</li>
<li><a href="#" data-help-guide="dept-coordination">Coordinamento</a>: Extra credits, Task flow</li>
<li><a href="#" data-help-guide="dept-formation">Formazione</a>: Formation pipeline, Access to reserved documents</li>
<li><a href="#" data-help-guide="dept-reward">Reward</a>: Credits in circulation, Compensation runs, Anomaly report</li>
<li><a href="#" data-help-guide="dept-communication">Communication</a>: Start Here cards</li>
<li><a href="#" data-help-guide="dept-archive">Archive &amp; Data</a>: Archive tools, Deleted documents, Translation prompt</li>
</ul>
</details>
<p><a class="btn" href="#" data-tab="mydepartment">Apri My Department</a></p>$help_guide$, 180, now(), 'migration 116');

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, updated_at, updated_by_email)
values ('dept-hr_en', 'dept-hr', 'en', null, 'HR', 'Applications, people, decisions', 'dept', array['dept:HR'], $help_guide$<p class="lead">HR follows every active person in the programme, from first contact to exit: who joins, how they are doing, and what is decided about them.</p>
<h2>The sections of this page</h2>
<h3>Team Applications</h3>
<p>Requests from <b>Join the Team</b>. Read them, talk with the person if useful, then choose <b>Recommend to Admin</b> or <b>Not accepted</b>. An Admin gives the final <b>Approve &amp; Promote to Operator</b>, and it can't be the same person who recommended.</p>
<h3>People</h3>
<p>Everyone on the team: role, standing, credits, reputation, qualifications, departments. You can search and filter. An at-risk mark is a computed hint to look closer: what counts is your decision, never the mark.</p>
<ul>
<li><b>Propose…</b> starts a decision about the person, always with a written reason.</li>
<li><b>History</b> shows past decisions, and <b>Activity</b> what the person has changed in the archive. The HR lead and Admins can see Activity.</li>
</ul>
<h3>Pending decisions</h3>
<p>What has been proposed and is waiting. Those entitled see <b>Approve</b> and <b>Reject</b>; whoever proposed can <b>Withdraw</b>.</p>
<table><tr><th>Decision</th><th>Who proposes</th><th>Who approves</th></tr>
<tr><td>Add or remove a qualification</td><td>HR</td><td>Admin</td></tr>
<tr><td>Watch list, on or off</td><td>HR</td><td>Applied at once, with a reason</td></tr>
<tr><td>Suspend, reinstate</td><td>HR</td><td>HR lead or Admin</td></tr>
<tr><td>Exclude</td><td>HR</td><td>Admin</td></tr>
<tr><td>Change role</td><td>HR lead</td><td>Admin</td></tr>
<tr><td>Board misuse, posting block</td><td>Coordinator or board editor</td><td>Formation lead, HR lead or Admin</td></tr></table>
<p>The proposer never approves. A suspended person can't claim or be given tasks. Excluding keeps the account and all its history.</p>
<h2>A suggested rhythm</h2>
<ul>
<li><b>A few times a week:</b> new applications, and Pending decisions. Nobody should wait in silence.</li>
<li><b>Every week:</b> look down People for those going quiet or marked. Start with a conversation.</li>
<li><b>Every month:</b> who is new and needs a first task? Which skills is the team missing? Ask Communication to help recruit. <b>Print Reports</b> gives a roster for a meeting, if you have that tab.</li>
</ul>
<p><a class="btn" href="#" data-tab="mydepartment">Open My Department</a></p>$help_guide$, 190, now(), 'migration 116');

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, updated_at, updated_by_email)
values ('dept-hr_it', 'dept-hr', 'it', null, 'HR', 'Candidature, persone, decisioni', 'dept', array['dept:HR'], $help_guide$<p class="lead">HR segue ogni persona attiva nel programma, dal primo contatto all'uscita: chi entra, come sta andando, e che cosa si decide su di lei.</p>
<h2>Le sezioni di questa pagina</h2>
<h3>Team Applications</h3>
<p>Le richieste da <b>Join the Team</b>. Leggile, parla con la persona se serve, poi scegli <b>Recommend to Admin</b> o <b>Not accepted</b>. Un Admin dà il definitivo <b>Approve &amp; Promote to Operator</b>, e non può essere chi ha raccomandato.</p>
<h3>People</h3>
<p>Tutto il team: ruolo, posizione, crediti, reputazione, qualifiche, reparti. Puoi cercare e filtrare. Il segno di rischio è un'indicazione calcolata per guardare meglio: conta la tua decisione, mai il segno.</p>
<ul>
<li><b>Propose…</b> avvia una decisione sulla persona, sempre con un motivo scritto.</li>
<li><b>History</b> mostra le decisioni passate, e <b>Activity</b> ciò che la persona ha modificato in archivio. Activity la vedono il responsabile di HR e gli Admin.</li>
</ul>
<h3>Pending decisions</h3>
<p>Ciò che è stato proposto e aspetta. Chi ne ha titolo vede <b>Approve</b> e <b>Reject</b>; chi ha proposto può fare <b>Withdraw</b>.</p>
<table><tr><th>Decisione</th><th>Chi propone</th><th>Chi approva</th></tr>
<tr><td>Aggiungere o togliere una qualifica</td><td>HR</td><td>Admin</td></tr>
<tr><td>Lista di osservazione, sì o no</td><td>HR</td><td>Si applica subito, con un motivo</td></tr>
<tr><td>Sospendere, riammettere</td><td>HR</td><td>Responsabile di HR o Admin</td></tr>
<tr><td>Escludere</td><td>HR</td><td>Admin</td></tr>
<tr><td>Cambiare ruolo</td><td>Responsabile di HR</td><td>Admin</td></tr>
<tr><td>Abuso di bacheca, blocco delle pubblicazioni</td><td>Coordinatore o chi cura la bacheca</td><td>Responsabile di Formazione, di HR o Admin</td></tr></table>
<p>Chi propone non approva mai. Una persona sospesa non può prendere né ricevere task. Escludere conserva l'account e tutta la sua storia.</p>
<h2>Un ritmo suggerito</h2>
<ul>
<li><b>Alcune volte a settimana:</b> nuove candidature e Pending decisions. Nessuno deve aspettare nel silenzio.</li>
<li><b>Ogni settimana:</b> scorri People per chi si fa silenzioso o è segnato. Comincia con una conversazione.</li>
<li><b>Ogni mese:</b> chi è nuovo e ha bisogno di un primo task? Quali competenze mancano al team? Chiedi a Communication di aiutare a reclutare. <b>Print Reports</b> dà un elenco per una riunione, se hai quella scheda.</li>
</ul>
<p><a class="btn" href="#" data-tab="mydepartment">Apri My Department</a></p>$help_guide$, 190, now(), 'migration 116');

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, updated_at, updated_by_email)
values ('dept-coordination_en', 'dept-coordination', 'en', null, 'Coordination', 'Extra credits and the flow of tasks', 'dept', array['dept:COORD'], $help_guide$<p class="lead">Coordination keeps the flow of work orderly, from translation to publication. This page gives the overview; the work itself happens in <b>Tasks</b>.</p>
<h2>The sections of this page</h2>
<h3>Extra credits awaiting approval</h3>
<p>Appears when a task carries extras above the threshold, with the reason given. The Coordination lead or an Admin approves. Until then the task can be worked on, but it can't receive a positive verdict.</p>
<h3>Task flow</h3>
<p>A live count of the open work: <b>Open</b>, <b>Claimed</b>, <b>Awaiting review</b>, <b>Awaiting publish</b>, <b>Overdue</b>. It shows where things pile up and whom to contact. It is read-only: to act, go to <b>Tasks → Team overview</b>.</p>
<h2>A suggested rhythm</h2>
<ul>
<li><b>Every day:</b> approve or question extra credits, so that nobody's verdict is held up.</li>
<li><b>Every week:</b> read the flow. Many overdue: talk to the people. Much waiting for review: ask the Revisors, or review yourself. Little open work: create more.</li>
<li><b>Every week:</b> update the department's status and priorities, if you are the lead.</li>
<li><b>Before each month:</b> plan the Word of Life with Stella's team in <b>Proposals → Word of Life</b>.</li>
</ul>
<p><a href="#" data-help-guide="coordinate-team">How to create and follow tasks</a></p>
<p><a class="btn" href="#" data-tab="mydepartment">Open My Department</a></p>$help_guide$, 200, now(), 'migration 116');

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, updated_at, updated_by_email)
values ('dept-coordination_it', 'dept-coordination', 'it', null, 'Coordinamento', 'Crediti extra e flusso dei task', 'dept', array['dept:COORD'], $help_guide$<p class="lead">Coordinamento tiene ordinato il flusso di lavoro, dalla traduzione alla pubblicazione. Questa pagina dà il quadro; il lavoro vero e proprio avviene in <b>Tasks</b>.</p>
<h2>Le sezioni di questa pagina</h2>
<h3>Extra credits awaiting approval</h3>
<p>Compare quando un task porta extra sopra la soglia, con il motivo dato. Approva il responsabile di Coordinamento o un Admin. Fino ad allora si può lavorare al task, ma non può ricevere un verdetto positivo.</p>
<h3>Task flow</h3>
<p>Un conteggio aggiornato del lavoro aperto: <b>Open</b>, <b>Claimed</b>, <b>Awaiting review</b>, <b>Awaiting publish</b>, <b>Overdue</b>. Mostra dove le cose si accumulano e chi contattare. È di sola lettura: per agire, vai in <b>Tasks → Team overview</b>.</p>
<h2>Un ritmo suggerito</h2>
<ul>
<li><b>Ogni giorno:</b> approva o discuti i crediti extra, così nessun verdetto resta bloccato.</li>
<li><b>Ogni settimana:</b> leggi il flusso. Molti in ritardo: parla con le persone. Molti in attesa di revisione: chiedi ai Revisori, o rivedi tu. Poco lavoro aperto: creane altro.</li>
<li><b>Ogni settimana:</b> aggiorna stato e priorità del reparto, se sei il responsabile.</li>
<li><b>Prima di ogni mese:</b> programma la Parola di Vita con il team di Stella in <b>Proposals → Word of Life</b>.</li>
</ul>
<p><a href="#" data-help-guide="coordinate-team">Come creare e seguire i task</a></p>
<p><a class="btn" href="#" data-tab="mydepartment">Apri My Department</a></p>$help_guide$, 200, now(), 'migration 116');

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, updated_at, updated_by_email)
values ('dept-formation_en', 'dept-formation', 'en', null, 'Formation', 'Pipeline and reserved documents', 'dept', array['dept:FORM'], $help_guide$<p class="lead">Formation builds and runs the paths, brings material into the archive through the normal review, and its members usually look after the boards.</p>
<h2>The sections of this page</h2>
<h3>Formation pipeline</h3>
<p>Every path, split into <b>In progress</b> (drafts) and <b>Published</b>. Open one to help or coordinate. This is where the lead sees what the team is writing.</p>
<h3>Access to reserved documents</h3>
<p>Search for a person and enable them to read reserved documents, or take it away. A short reason is optional. Only Formation members and Admins see this list, and every change is in the log.</p>
<h2>Who decides what</h2>
<ul>
<li><b>Creating paths:</b> members of this department.</li>
<li><b>Looking after a board:</b> named editors, board by board, a separate matter.</li>
<li><b>Reserved proposals:</b> another Formation member or an Admin approves.</li>
<li><b>Board misuse:</b> the Formation lead or the HR lead approves what an editor proposes.</li>
</ul>
<h2>A suggested rhythm</h2>
<ul>
<li><b>Every week:</b> the lead reads the pipeline and asks how each draft is going. Use the Team channel, and <b>Formatori notes</b> for advice on a path.</li>
<li><b>Every month:</b> which paths should open next? Who is enabled for reserved documents, and do they still need it?</li>
</ul>
<p><a href="#" data-help-guide="role-formator">Being a formator</a> · <a href="#" data-help-guide="build-path">Build a path</a></p>
<p><a class="btn" href="#" data-tab="mydepartment">Open My Department</a></p>$help_guide$, 210, now(), 'migration 116');

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, updated_at, updated_by_email)
values ('dept-formation_it', 'dept-formation', 'it', null, 'Formazione', 'Pipeline e documenti riservati', 'dept', array['dept:FORM'], $help_guide$<p class="lead">Formazione costruisce e guida i percorsi, porta materiale in archivio con la revisione normale, e di solito i suoi membri curano le bacheche.</p>
<h2>Le sezioni di questa pagina</h2>
<h3>Formation pipeline</h3>
<p>Tutti i percorsi, divisi in <b>In progress</b> (bozze) e <b>Published</b>. Aprine uno per aiutare o coordinare. Qui il responsabile vede che cosa sta scrivendo il team.</p>
<h3>Access to reserved documents</h3>
<p>Cerca una persona e abilitala a leggere i documenti riservati, o toglile l'abilitazione. Un breve motivo è facoltativo. Solo i membri di Formazione e gli Admin vedono questo elenco, e ogni cambiamento è nel registro.</p>
<h2>Chi decide che cosa</h2>
<ul>
<li><b>Creare percorsi:</b> i membri di questo reparto.</li>
<li><b>Curare una bacheca:</b> chi è nominato, bacheca per bacheca: è una cosa distinta.</li>
<li><b>Proposte riservate:</b> approva un altro membro di Formazione o un Admin.</li>
<li><b>Abuso di bacheca:</b> il responsabile di Formazione o di HR approva ciò che propone chi cura la bacheca.</li>
</ul>
<h2>Un ritmo suggerito</h2>
<ul>
<li><b>Ogni settimana:</b> il responsabile legge la pipeline e chiede come va ogni bozza. Usate il Team channel, e <b>Formatori notes</b> per i consigli su un percorso.</li>
<li><b>Ogni mese:</b> quali percorsi aprire ora? Chi è abilitato ai riservati, e ne ha ancora bisogno?</li>
</ul>
<p><a href="#" data-help-guide="role-formator">Essere formatore</a> · <a href="#" data-help-guide="build-path">Costruire un percorso</a></p>
<p><a class="btn" href="#" data-tab="mydepartment">Apri My Department</a></p>$help_guide$, 210, now(), 'migration 116');

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, updated_at, updated_by_email)
values ('dept-reward_en', 'dept-reward', 'en', null, 'Reward', 'Credits, compensation runs, anomalies', 'dept', array['dept:RF'], $help_guide$<p class="lead">Reward sees to it that credits and compensation are fair, transparent and proof against mistakes. It owns the rates and rules; an Admin applies them only after a decision.</p>
<div class="note">Figures for rates, thresholds and reputation are still to be defined. This guide explains the mechanism only.</div>
<h2>The sections of this page</h2>
<h3>Credits in circulation</h3>
<p>Live totals: posted, claimed, awaiting review, approved, redeemed, set against the budget. It is read-only. Budget top-ups are the Owner's, through an Admin.</p>
<h3>Compensation runs</h3>
<p>The record that credits were turned into money. A Reward member prepares a run with <b>New compensation run</b>, listing the people and amounts. An Admin who didn't prepare it decides. The same credits can't enter two runs, and nothing is ever deleted.</p>
<h3>Anomaly report</h3>
<p>Two lists to look at, not accusations: every task with extra credits, and Operators whose approved credits have grown far ahead of their published work.</p>
<h3>Policy</h3>
<p>The lead proposes changes to rates, reputation tiers and thresholds with <b>Propose change</b>, with the reason. The team reviews it, and an Admin who isn't the proposer decides. Nobody can change a value directly, Admins included.</p>
<h2>A suggested rhythm</h2>
<ul>
<li><b>Every week:</b> look at the anomaly report. If something is odd, ask Coordination before concluding anything.</li>
<li><b>Every month:</b> compare credits in circulation with the budget, and note what should be proposed.</li>
<li><b>At each compensation period:</b> prepare the run, once the policy has been decided. Keep whatever records the law and the Movement's rules require.</li>
</ul>
<p>Tasks an Admin approved themselves during testing are recognisable: leave them out of real reports.</p>
<p><a class="btn" href="#" data-tab="mydepartment">Open My Department</a></p>$help_guide$, 220, now(), 'migration 116');

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, updated_at, updated_by_email)
values ('dept-reward_it', 'dept-reward', 'it', null, 'Reward', 'Crediti, compensi, anomalie', 'dept', array['dept:RF'], $help_guide$<p class="lead">Reward fa sì che crediti e compensi siano equi, trasparenti e protetti dagli errori. Sue sono le tariffe e le regole; un Admin le applica solo dopo una decisione.</p>
<div class="note">Le cifre di tariffe, soglie e reputazione sono ancora da definire. Questa guida spiega solo il meccanismo.</div>
<h2>Le sezioni di questa pagina</h2>
<h3>Credits in circulation</h3>
<p>Totali aggiornati: pubblicati, presi, in attesa di revisione, approvati, riscattati, a fronte del budget. È di sola lettura. Le ricariche del budget sono dell'Owner, tramite un Admin.</p>
<h3>Compensation runs</h3>
<p>La traccia che dei crediti sono diventati denaro. Un membro di Reward prepara un'esecuzione con <b>New compensation run</b>, elencando persone e importi. Decide un Admin che non l'ha preparata. Gli stessi crediti non possono entrare in due esecuzioni, e nulla si cancella mai.</p>
<h3>Anomaly report</h3>
<p>Due elenchi da guardare, non accuse: ogni task con crediti extra, e gli Operatori i cui crediti approvati sono cresciuti molto più del lavoro pubblicato.</p>
<h3>Policy</h3>
<p>Il responsabile propone modifiche a tariffe, livelli di reputazione e soglie con <b>Propose change</b>, con il motivo. Il team la esamina, e decide un Admin diverso da chi propone. Nessuno può cambiare un valore direttamente, Admin compresi.</p>
<h2>Un ritmo suggerito</h2>
<ul>
<li><b>Ogni settimana:</b> guarda il report delle anomalie. Se qualcosa è strano, chiedi a Coordinamento prima di concludere.</li>
<li><b>Ogni mese:</b> confronta i crediti in circolazione con il budget, e annota che cosa proporre.</li>
<li><b>A ogni periodo di compensi:</b> prepara l'esecuzione, una volta decisa la regola. Conserva i documenti richiesti dalla legge e dalle regole del Movimento.</li>
</ul>
<p>I task che un Admin si è approvato da solo durante le prove sono riconoscibili: lasciali fuori dai report veri.</p>
<p><a class="btn" href="#" data-tab="mydepartment">Apri My Department</a></p>$help_guide$, 220, now(), 'migration 116');

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, updated_at, updated_by_email)
values ('dept-communication_en', 'dept-communication', 'en', null, 'Communication', 'Start Here cards and being heard', 'dept', array['dept:COMM'], $help_guide$<p class="lead">Communication makes sure people know the archive exists, know what is new and know how to use it, and that a first-time User feels welcome before anything else.</p>
<h2>The sections of this page</h2>
<h3>Start Here cards</h3>
<p>What Users see first. Think of the person who will find it hardest: little English, basic Urdu reading, on a phone. It is a welcome, not a manual.</p>
<ul>
<li><b>New card:</b> choose a <b>Section</b>, write <b>Title (Urdu)</b> and optionally the text. English is an optional help.</li>
<li><b>Media type</b> and <b>Link:</b> a video published elsewhere, or a link to a tab of the app.</li>
<li><b>Thumbnail</b> is an image, and <b>Order</b> sets the position. A card appears only when published.</li>
</ul>
<h2>Your work outside this page</h2>
<ul>
<li><b>Share with us:</b> read what people share, thank them and reply. Every lead sees the same messages; your department makes sure nobody goes unheard.</li>
<li><b>Announcements:</b> an Admin publishes them, so prepare the words and pass them on.</li>
<li><b>These guides, and short videos:</b> tell an Admin when a guide no longer matches the app.</li>
<li><b>Recruitment:</b> promote HR's campaigns.</li>
</ul>
<h2>A suggested rhythm</h2>
<ul>
<li><b>Every day or two:</b> Share with us.</li>
<li><b>Every week:</b> is Start Here still fresh? Is something new worth a card or a word on the boards?</li>
<li><b>At each release:</b> what changes for people, said simply.</li>
</ul>
<p><a class="btn" href="#" data-tab="mydepartment">Open My Department</a></p>$help_guide$, 230, now(), 'migration 116');

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, updated_at, updated_by_email)
values ('dept-communication_it', 'dept-communication', 'it', null, 'Communication', 'Le schede di Start Here e l''ascolto', 'dept', array['dept:COMM'], $help_guide$<p class="lead">Communication fa sì che le persone sappiano che l'archivio esiste, che cosa c'è di nuovo e come usarlo, e che chi arriva per la prima volta si senta accolto prima di tutto.</p>
<h2>Le sezioni di questa pagina</h2>
<h3>Start Here cards</h3>
<p>Ciò che gli User vedono per primo. Pensa a chi farà più fatica: poco inglese, lettura dell'urdu di base, al telefono. È un'accoglienza, non un manuale.</p>
<ul>
<li><b>New card:</b> scegli una <b>Section</b>, scrivi <b>Title (Urdu)</b> e, se vuoi, il testo. L'inglese è un aiuto facoltativo.</li>
<li><b>Media type</b> e <b>Link:</b> un video pubblicato altrove, o un collegamento a una scheda dell'app.</li>
<li><b>Thumbnail</b> è un'immagine, e <b>Order</b> decide la posizione. Una scheda compare solo se pubblicata.</li>
</ul>
<h2>Il tuo lavoro fuori da questa pagina</h2>
<ul>
<li><b>Share with us:</b> leggi ciò che le persone condividono, ringrazia e rispondi. Tutti i responsabili vedono gli stessi messaggi; il vostro reparto fa sì che nessuno resti senza ascolto.</li>
<li><b>Announcements:</b> li pubblica un Admin, quindi prepara le parole e passagliele.</li>
<li><b>Queste guide, e brevi video:</b> avvisa un Admin quando una guida non corrisponde più all'app.</li>
<li><b>Reclutamento:</b> promuovi le campagne di HR.</li>
</ul>
<h2>Un ritmo suggerito</h2>
<ul>
<li><b>Ogni uno o due giorni:</b> Share with us.</li>
<li><b>Ogni settimana:</b> Start Here è ancora fresco? C'è qualcosa di nuovo che merita una scheda o una parola sulle bacheche?</li>
<li><b>A ogni nuova versione:</b> che cosa cambia per le persone, detto semplicemente.</li>
</ul>
<p><a class="btn" href="#" data-tab="mydepartment">Apri My Department</a></p>$help_guide$, 230, now(), 'migration 116');

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, updated_at, updated_by_email)
values ('dept-archive_en', 'dept-archive', 'en', null, 'Archive & Data', 'Cataloguing tools and correct records', 'dept', array['dept:ARCHIVE'], $help_guide$<p class="lead">Archive &amp; Data keeps the archive's records correct: the catalogue, the texts as stored, and the links between versions. It corrects what the others produce; it doesn't decide what work is done, by whom or for how much.</p>
<h2>The sections of this page</h2>
<h3>Archive tools</h3>
<table><tr><th>Tool</th><th>What it does</th></tr>
<tr><td><b>Hayat Index</b></td><td>Browse the Hayat magazine's register. Extracting an entry is for Admins</td></tr>
<tr><td><b>Match Review</b></td><td>Confirm or refuse automatic matches with existing documents</td></tr>
<tr><td><b>Work Consolidation</b></td><td>Bring together records that are the same work</td></tr>
<tr><td><b>Hayat Editor</b></td><td>Correct a register entry</td></tr>
<tr><td><b>Bulk Import</b></td><td>Admins only: a batch of new documents</td></tr></table>
<h3>Deleted documents (Admins)</h3>
<p>Each with who deleted it, when and why, and <b>Restore</b>. Nobody can erase a document through the app.</p>
<h3>Translation prompt (Admins)</h3>
<p>What the <b>Translate</b> button copies. An Admin saves a new version with a short note, after the Owner has decided a question of terminology. Old versions stay.</p>
<h2>Rules to keep in mind</h2>
<ul>
<li>A document's date must equal the date in its own title.</li>
<li>Every language version is its own record, linked in one Work. A person decides each link.</li>
<li>A Word of Life has its own month. A magazine issue is a separate record.</li>
<li>A tool may report how a term is used; only the Owner decides it.</li>
</ul>
<h2>A suggested rhythm</h2>
<ul>
<li><b>Every week:</b> work through some of Match Review and Work Consolidation, and agree in the Team channel who does what, so two people don't do the same.</li>
<li><b>Every month:</b> look over what was published recently: dates, links, stars.</li>
</ul>
<p><a class="btn" href="#" data-tab="mydepartment">Open My Department</a></p>$help_guide$, 240, now(), 'migration 116');

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, updated_at, updated_by_email)
values ('dept-archive_it', 'dept-archive', 'it', null, 'Archive & Data', 'Strumenti di catalogo e record corretti', 'dept', array['dept:ARCHIVE'], $help_guide$<p class="lead">Archive &amp; Data tiene corretti i record dell'archivio: il catalogo, i testi come sono conservati, i collegamenti tra le versioni. Corregge ciò che gli altri producono; non decide che lavoro si fa, chi lo fa né quanto vale.</p>
<h2>Le sezioni di questa pagina</h2>
<h3>Archive tools</h3>
<table><tr><th>Strumento</th><th>Che cosa fa</th></tr>
<tr><td><b>Hayat Index</b></td><td>Sfoglia il registro della rivista Hayat. Estrarre una voce spetta agli Admin</td></tr>
<tr><td><b>Match Review</b></td><td>Conferma o rifiuta gli abbinamenti automatici con documenti esistenti</td></tr>
<tr><td><b>Work Consolidation</b></td><td>Riunisce i record che sono la stessa opera</td></tr>
<tr><td><b>Hayat Editor</b></td><td>Corregge una voce del registro</td></tr>
<tr><td><b>Bulk Import</b></td><td>Solo Admin: un gruppo di nuovi documenti</td></tr></table>
<h3>Deleted documents (Admin)</h3>
<p>Ciascuno con chi l'ha cancellato, quando e perché, e <b>Restore</b>. Nessuno può eliminare un documento dall'app.</p>
<h3>Translation prompt (Admin)</h3>
<p>Ciò che copia il pulsante <b>Translate</b>. Un Admin salva una nuova versione con una breve nota, dopo che l'Owner ha deciso una questione di terminologia. Le vecchie versioni restano.</p>
<h2>Regole da tenere a mente</h2>
<ul>
<li>La data di un documento deve coincidere con quella del suo titolo.</li>
<li>Ogni versione linguistica è un record a sé, collegato in un'unica opera. Ogni collegamento lo decide una persona.</li>
<li>Una Parola di Vita ha il suo mese. Un numero della rivista è un record distinto.</li>
<li>Uno strumento può riportare come si usa un termine; lo decide solo l'Owner.</li>
</ul>
<h2>Un ritmo suggerito</h2>
<ul>
<li><b>Ogni settimana:</b> lavora su una parte di Match Review e Work Consolidation, e accordatevi nel Team channel su chi fa che cosa, perché due persone non facciano lo stesso lavoro.</li>
<li><b>Ogni mese:</b> rivedi ciò che è stato pubblicato di recente: date, collegamenti, stelle.</li>
</ul>
<p><a class="btn" href="#" data-tab="mydepartment">Apri My Department</a></p>$help_guide$, 240, now(), 'migration 116');

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, updated_at, updated_by_email)
values ('coordinate-team_en', 'coordinate-team', 'en', null, 'Create and follow tasks', 'New task, Team overview, Messages', 'run', array['coordinator'], $help_guide$<p class="lead">How to give work to the team and follow it, in the app. For what the role involves, see <a href="#" data-help-guide="role-coordinator">Being a Coordinator</a>.</p>
<h2>Create a task</h2>
<ol>
<li><b>Start it.</b> <b>Tasks Store → + New task</b>, or <b>Create Task</b> on a document, or <b>Create task</b> on a message.</li>
<li><b>Title and description:</b> say exactly what is expected.</li>
<li><b>Category.</b> Translation and Revision can be taken only by those with that qualification.</li>
<li><b>Pages and credits.</b> Base credits are the category's rate times the pages. Extras need a reason, and above the threshold the Coordination lead must approve them.</li>
<li><b>Due date,</b> and leave it open or assign it to someone.</li>
<li>Press <b>Create task</b>.</li>
</ol>
<h2>Follow the work: Team overview</h2>
<ul>
<li><b>Overdue only</b> shows who is late.</li>
<li><b>Reassign</b> moves a task to someone else, with no penalty.</li>
<li><b>Free up (back to open)</b> takes it back: it needs a reason and lowers the person's reputation.</li>
<li><b>Create task to redo this</b> opens a new task after a rejection.</li>
<li><b>Delete</b> removes a task permanently: use it with care.</li>
</ul>
<h2>Messages</h2>
<p>Reports from everyone. <b>Reply</b>, <b>Dismiss</b> when resolved (nothing is deleted, and <b>Show dismissed</b> brings it back), or <b>Create task</b>, which fills in the title, description and document.</p>
<details><summary>The month's Word of Life</summary>
<p><b>Proposals → Word of Life</b> shows the month's pieces. <b>Create a translation task</b> starts from the source. If a month's documents are in separate Works, <b>Link to this month</b> joins them: nothing merges by itself.</p>
</details>
<details><summary>On a document</summary>
<ul>
<li><b>Edit:</b> change its details.</li>
<li><b>Set preferred:</b> choose which version carries the star.</li>
<li><b>Change history:</b> who changed what, written by the database.</li>
<li><b>Tasks for this document:</b> what has been done on it.</li>
</ul>
</details>
<details><summary>Readers</summary>
<p><b>Read aloud → Readers</b> shows each reader's published, waiting, sent-back and not-accepted readings. It helps entrust the most important texts to the best readers.</p>
</details>
<p><a class="btn" href="#" data-tab="tasks">Open Tasks</a></p>$help_guide$, 250, now(), 'migration 116');

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, updated_at, updated_by_email)
values ('coordinate-team_it', 'coordinate-team', 'it', null, 'Creare e seguire i task', 'New task, Team overview, Messages', 'run', array['coordinator'], $help_guide$<p class="lead">Come dare lavoro al team e seguirlo, nell'app. Per che cosa comporta il ruolo, vedi <a href="#" data-help-guide="role-coordinator">Essere Coordinatore</a>.</p>
<h2>Creare un task</h2>
<ol>
<li><b>Avvialo.</b> <b>Tasks Store → + New task</b>, oppure <b>Create Task</b> su un documento, o <b>Create task</b> su un messaggio.</li>
<li><b>Titolo e descrizione:</b> di' esattamente che cosa ci si aspetta.</li>
<li><b>Categoria.</b> Traduzione e Revisione le può prendere solo chi ha quella qualifica.</li>
<li><b>Pagine e crediti.</b> I crediti base sono la tariffa della categoria per le pagine. Gli extra richiedono un motivo, e sopra la soglia deve approvarli il responsabile di Coordinamento.</li>
<li><b>Data di scadenza,</b> e lascialo aperto o assegnalo a qualcuno.</li>
<li>Premi <b>Create task</b>.</li>
</ol>
<h2>Seguire il lavoro: Team overview</h2>
<ul>
<li><b>Overdue only</b> mostra chi è in ritardo.</li>
<li><b>Reassign</b> passa un task a un altro, senza penalità.</li>
<li><b>Free up (back to open)</b> lo riprende: richiede un motivo e abbassa la reputazione della persona.</li>
<li><b>Create task to redo this</b> apre un nuovo task dopo un rifiuto.</li>
<li><b>Delete</b> toglie un task definitivamente: usalo con cautela.</li>
</ul>
<h2>Messages</h2>
<p>Le segnalazioni di tutti. <b>Reply</b>, <b>Dismiss</b> quando è risolta (non si cancella nulla, e <b>Show dismissed</b> la fa ricomparire), oppure <b>Create task</b>, che compila titolo, descrizione e documento.</p>
<details><summary>La Parola di Vita del mese</summary>
<p><b>Proposals → Word of Life</b> mostra i pezzi del mese. <b>Create a translation task</b> parte dalla fonte. Se i documenti di un mese stanno in opere separate, <b>Link to this month</b> li unisce: nulla si unisce da solo.</p>
</details>
<details><summary>Su un documento</summary>
<ul>
<li><b>Edit:</b> cambia i suoi dati.</li>
<li><b>Set preferred:</b> sceglie quale versione porta la stella.</li>
<li><b>Change history:</b> chi ha cambiato che cosa, scritto dal database.</li>
<li><b>Tasks for this document:</b> che cosa è stato fatto su di esso.</li>
</ul>
</details>
<details><summary>Readers</summary>
<p><b>Read aloud → Readers</b> mostra per ogni lettore le letture pubblicate, in attesa, rimandate e non accettate. Aiuta ad affidare i testi più importanti ai lettori migliori.</p>
</details>
<p><a class="btn" href="#" data-tab="tasks">Apri Tasks</a></p>$help_guide$, 250, now(), 'migration 116');

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, updated_at, updated_by_email)
values ('administer_en', 'administer', 'en', null, 'Administer', 'Publish, users, options, Drive', 'run', array['admin'], $help_guide$<p class="lead">How to do what only an Admin can do. For what the role means, see <a href="#" data-help-guide="role-admin">Being an Admin</a>.</p>
<h2>Close tasks and publish</h2>
<ol>
<li><b>Tasks → Publish Tasks:</b> what a Revisor has approved. <b>Open corrected file</b> to check it.</li>
<li><b>Publish</b> closes the task: credits and reputation are written, once. <b>Reject</b> needs a reason: no credits, and the same penalty as a Fail.</li>
<li><b>Documents ready to publish:</b> download the draft, upload the final PDF and the InPage file, and press Publish. The previous version stays, without the star.</li>
</ol>
<p>This second step can wait for a calmer moment: payment doesn't depend on it.</p>
<details><summary>Proposals and Drive</summary>
<ul>
<li><b>Files for Drive:</b> after approval, copy each PDF to Drive. The first time it asks for an authorised Google account. The Supabase copy is then removed.</li>
<li><b>Publish directly (Admin):</b> in the form, with no review. It is recorded.</li>
<li><b>+ New document</b>, Bulk Import, Hayat Extract: only you can add visible documents this way.</li>
</ul>
</details>
<details><summary>People: Users tab</summary>
<p>Change a role from the row. <b>Edit</b> changes the profile. <b>Propose exclusion</b> starts the decision with its reason. Qualifications and other decisions pass through <b>My Department → HR</b>.</p>
</details>
<details><summary>Options</summary>
<ul>
<li><b>Lists:</b> every dropdown in the app. Don't rename codes such as <code>TRANSLATOR</code> and <code>REVISOR</code>: the app uses them to decide who sees what.</li>
<li><b>Departments:</b> add and remove members, <b>Make lead</b> and <b>Remove lead</b>, on the Owner's decision.</li>
<li><b>Policy:</b> decide proposals. You can't decide your own, and no value changes any other way.</li>
<li><b>Maintenance:</b> one-off tools.</li>
</ul>
</details>
<details><summary>Money: Budget and runs</summary>
<p><b>Tasks → Budget:</b> top-ups, on the Owner's decision. <b>My Department → Reward:</b> decide a compensation run you didn't prepare. <b>Withdrawn Tasks</b> shows tasks taken out of the Store.</p>
</details>
<details><summary>Deleting and restoring</summary>
<p><b>Delete</b> in a document's editor asks for a reason and hides it from everyone. <b>My Department → Archive &amp; Data → Deleted documents</b> restores it. Nothing is erased, and the number is never reused.</p>
</details>
<details><summary>Reserved documents</summary>
<p><b>My Department → Formation → Access to reserved documents</b> enables a person. A reserved document is protected in the app, not on Drive.</p>
</details>
<details><summary>Readings: consent and files</summary>
<p><b>Read aloud → Readers</b>: withdraw consent on someone's behalf with <b>Withdraw consent</b>. The <b>Space</b> section shows what is used and <b>Erase</b> removes files nothing uses. This can't be undone. New texts can't be held once recordings reach 500 MB.</p>
</details>
<details><summary>Announcements, overview and these guides</summary>
<ul>
<li><b>Announcements:</b> shown once to everyone at their next sign-in.</li>
<li><b>Project overview:</b> all departments and the Users panel. It doesn't record who signs in, by decision.</li>
<li><b>Help:</b> open a guide and press <b>Edit</b> to change its title, line or HTML. Keep Italian and English together.</li>
</ul>
</details>$help_guide$, 260, now(), 'migration 116');

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, updated_at, updated_by_email)
values ('administer_it', 'administer', 'it', null, 'Amministrare', 'Pubblicare, utenti, opzioni, Drive', 'run', array['admin'], $help_guide$<p class="lead">Come fare ciò che può fare solo un Admin. Per che cosa significa il ruolo, vedi <a href="#" data-help-guide="role-admin">Essere Admin</a>.</p>
<h2>Chiudere i task e pubblicare</h2>
<ol>
<li><b>Tasks → Publish Tasks:</b> ciò che un Revisore ha approvato. <b>Open corrected file</b> per controllarlo.</li>
<li><b>Publish</b> chiude il task: crediti e reputazione vengono scritti, una sola volta. <b>Reject</b> richiede un motivo: niente crediti, e la stessa penalità di un Fail.</li>
<li><b>Documents ready to publish:</b> scarica la bozza, carica il PDF finale e il file InPage, e premi Publish. La versione precedente resta, senza la stella.</li>
</ol>
<p>Questo secondo passo può aspettare un momento più calmo: il pagamento non dipende da lì.</p>
<details><summary>Proposte e Drive</summary>
<ul>
<li><b>Files for Drive:</b> dopo l'approvazione, copia ogni PDF su Drive. La prima volta chiede un account Google autorizzato. La copia su Supabase viene poi tolta.</li>
<li><b>Publish directly (Admin):</b> nella scheda, senza revisione. Resta registrato.</li>
<li><b>+ New document</b>, Bulk Import, Hayat Extract: solo tu puoi aggiungere così documenti visibili.</li>
</ul>
</details>
<details><summary>Le persone: la scheda Users</summary>
<p>Cambia un ruolo dalla riga. <b>Edit</b> cambia il profilo. <b>Propose exclusion</b> avvia la decisione con il suo motivo. Qualifiche e altre decisioni passano da <b>My Department → HR</b>.</p>
</details>
<details><summary>Options</summary>
<ul>
<li><b>Elenchi:</b> tutte le tendine dell'app. Non rinominare codici come <code>TRANSLATOR</code> e <code>REVISOR</code>: l'app li usa per decidere chi vede che cosa.</li>
<li><b>Departments:</b> aggiungere e togliere membri, <b>Make lead</b> e <b>Remove lead</b>, su decisione dell'Owner.</li>
<li><b>Policy:</b> decidere le proposte. Non puoi decidere le tue, e nessun valore cambia in altro modo.</li>
<li><b>Maintenance:</b> strumenti una tantum.</li>
</ul>
</details>
<details><summary>Denaro: Budget e compensi</summary>
<p><b>Tasks → Budget:</b> ricariche, su decisione dell'Owner. <b>My Department → Reward:</b> decidere un'esecuzione di compensi che non hai preparato. <b>Withdrawn Tasks</b> mostra i task tolti dallo Store.</p>
</details>
<details><summary>Cancellare e ripristinare</summary>
<p><b>Delete</b> nell'editor di un documento chiede un motivo e lo nasconde a tutti. <b>My Department → Archive &amp; Data → Deleted documents</b> lo ripristina. Nulla viene eliminato, e il numero non si riusa mai.</p>
</details>
<details><summary>Documenti riservati</summary>
<p><b>My Department → Formation → Access to reserved documents</b> abilita una persona. Un documento riservato è protetto nell'app, non su Drive.</p>
</details>
<details><summary>Letture: consenso e file</summary>
<p><b>Read aloud → Readers</b>: ritira il consenso per conto di qualcuno con <b>Withdraw consent</b>. La sezione <b>Space</b> mostra quanto è usato ed <b>Erase</b> toglie i file che nulla usa. Non si può annullare. Non si possono tenere nuovi testi quando le registrazioni arrivano a 500 MB.</p>
</details>
<details><summary>Annunci, quadro generale e queste guide</summary>
<ul>
<li><b>Announcements:</b> mostrati una volta a tutti al prossimo accesso.</li>
<li><b>Project overview:</b> tutti i reparti e il pannello Users. Non registra chi accede, per scelta.</li>
<li><b>Help:</b> apri una guida e premi <b>Modifica</b> per cambiarne titolo, riga o HTML. Tieni allineati italiano e inglese.</li>
</ul>
</details>$help_guide$, 260, now(), 'migration 116');

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, updated_at, updated_by_email)
values ('who-does-what_en', 'who-does-what', 'en', null, 'Who can do what', 'Roles, qualifications, departments', 'ref', array['operator'], $help_guide$<p class="lead">Three things combine: your <b>role</b> sets how much you can do, your <b>qualifications</b> what kind of work you can take, and your <b>departments</b> which responsibilities you share.</p>
<h2>Roles</h2>
<table><tr><th>Role</th><th>What it adds</th></tr>
<tr><td><b>User</b></td><td>Read the archive and Boards, follow paths, read aloud, report a problem, share, apply to join the team</td></tr>
<tr><td><b>Operator</b></td><td>Propose content, claim and submit tasks, use Translate and the InPage Converter. A post on a board appears at once</td></tr>
<tr><td><b>Coordinator</b></td><td>Create and assign tasks, give verdicts, decide proposals and readings, answer Messages, edit documents</td></tr>
<tr><td><b>Admin</b></td><td>Close tasks, publish directly, delete and restore, change roles, options and announcements. A technical role: it carries out decisions</td></tr></table>
<h2>Qualifications</h2>
<table><tr><th>Qualification</th><th>What it opens</th></tr>
<tr><td><b>Translator</b></td><td>Translation tasks</td></tr>
<tr><td><b>Revisor</b></td><td>Revision tasks, Review Tasks, and proposals to review</td></tr>
<tr><td><b>AUDIO_REVIEWER</b></td><td>Listening to readings</td></tr></table>
<p>HR proposes a qualification, and an Admin applies it. A board's editors are named board by board.</p>
<h2>Who decides what</h2>
<table><tr><th>Decision</th><th>Proposes</th><th>Approves</th></tr>
<tr><td>Publish new content</td><td>Anyone on the team</td><td>A Revisor or Coordinator, not the proposer</td></tr>
<tr><td>Publish reserved content</td><td>Formation or Admin</td><td>Another Formation member or Admin</td></tr>
<tr><td>Close a reviewed task</td><td>Revisor or Coordinator, by verdict</td><td>Admin</td></tr>
<tr><td>Extra credits above the threshold</td><td>Coordinator</td><td>Coordination lead</td></tr>
<tr><td>Admit an applicant</td><td>HR</td><td>Admin</td></tr>
<tr><td>Suspend a person</td><td>HR</td><td>HR lead or Admin</td></tr>
<tr><td>Exclude a person</td><td>HR</td><td>Owner, through an Admin</td></tr>
<tr><td>Penalise board misuse</td><td>Board editor or Coordinator</td><td>Formation lead or HR lead</td></tr>
<tr><td>Change a rate or threshold</td><td>The owning department's lead</td><td>Admin who isn't the proposer, after team review</td></tr>
<tr><td>A compensation run</td><td>Reward</td><td>Reward lead and Owner</td></tr>
<tr><td>Appoint a department lead</td><td>Owner</td><td>Owner</td></tr>
<tr><td>A canonical translation term</td><td>Anyone</td><td>Owner</td></tr></table>
<p>The proposer never approves. During development Admins are the exception, and every action of theirs is recorded.</p>
<details><summary>Levels of a document</summary>
<ul>
<li><b>Public</b> and <b>Private:</b> visible to registered users. Public means it may also exist outside the archive.</li>
<li><b>Reserved:</b> Admins, Formation and people they enable. For anyone else, it doesn't exist in the app.</li>
</ul>
<p>A level decides what the app shows. PDFs stay on Drive with a public link.</p>
</details>$help_guide$, 270, now(), 'migration 116');

insert into public.help_pages (slug, guide_key, language, role, title, summary, section, audience, html_content, sort_order, updated_at, updated_by_email)
values ('who-does-what_it', 'who-does-what', 'it', null, 'Chi può fare cosa', 'Ruoli, qualifiche, reparti', 'ref', array['operator'], $help_guide$<p class="lead">Tre cose si combinano: il <b>ruolo</b> dice quanto puoi fare, le <b>qualifiche</b> che tipo di lavoro puoi prendere, i <b>reparti</b> quali responsabilità condividi.</p>
<h2>Ruoli</h2>
<table><tr><th>Ruolo</th><th>Che cosa aggiunge</th></tr>
<tr><td><b>User</b></td><td>Leggere l'archivio e le bacheche, seguire i percorsi, leggere ad alta voce, segnalare un problema, condividere, candidarsi al team</td></tr>
<tr><td><b>Operatore</b></td><td>Proporre contenuti, prendere e consegnare task, usare Translate e l'InPage Converter. Un post in bacheca compare subito</td></tr>
<tr><td><b>Coordinatore</b></td><td>Creare e assegnare task, dare verdetti, decidere su proposte e letture, rispondere in Messages, modificare documenti</td></tr>
<tr><td><b>Admin</b></td><td>Chiudere task, pubblicare direttamente, cancellare e ripristinare, cambiare ruoli, opzioni e annunci. Un ruolo tecnico: esegue le decisioni</td></tr></table>
<h2>Qualifiche</h2>
<table><tr><th>Qualifica</th><th>Che cosa apre</th></tr>
<tr><td><b>Translator</b></td><td>Task di traduzione</td></tr>
<tr><td><b>Revisor</b></td><td>Task di revisione, Review Tasks e proposte da rivedere</td></tr>
<tr><td><b>AUDIO_REVIEWER</b></td><td>L'ascolto delle letture</td></tr></table>
<p>HR propone una qualifica, e un Admin la applica. Chi cura una bacheca è nominato bacheca per bacheca.</p>
<h2>Chi decide che cosa</h2>
<table><tr><th>Decisione</th><th>Propone</th><th>Approva</th></tr>
<tr><td>Pubblicare contenuti nuovi</td><td>Chiunque nel team</td><td>Un Revisore o Coordinatore, non chi propone</td></tr>
<tr><td>Pubblicare contenuti riservati</td><td>Formazione o Admin</td><td>Un altro membro di Formazione o un Admin</td></tr>
<tr><td>Chiudere un task rivisto</td><td>Revisore o Coordinatore, col verdetto</td><td>Admin</td></tr>
<tr><td>Crediti extra sopra la soglia</td><td>Coordinatore</td><td>Responsabile di Coordinamento</td></tr>
<tr><td>Ammettere un candidato</td><td>HR</td><td>Admin</td></tr>
<tr><td>Sospendere una persona</td><td>HR</td><td>Responsabile di HR o Admin</td></tr>
<tr><td>Escludere una persona</td><td>HR</td><td>Owner, tramite un Admin</td></tr>
<tr><td>Penalizzare un abuso di bacheca</td><td>Chi cura la bacheca o un Coordinatore</td><td>Responsabile di Formazione o di HR</td></tr>
<tr><td>Cambiare una tariffa o una soglia</td><td>Il responsabile del reparto competente</td><td>Un Admin diverso da chi propone, dopo l'esame del team</td></tr>
<tr><td>Un'esecuzione di compensi</td><td>Reward</td><td>Responsabile di Reward e Owner</td></tr>
<tr><td>Nominare un responsabile di reparto</td><td>Owner</td><td>Owner</td></tr>
<tr><td>Un termine canonico di traduzione</td><td>Chiunque</td><td>Owner</td></tr></table>
<p>Chi propone non approva mai. Durante lo sviluppo gli Admin sono l'eccezione, e ogni loro azione è registrata.</p>
<details><summary>I livelli di un documento</summary>
<ul>
<li><b>Public</b> e <b>Private:</b> visibili agli utenti registrati. Public significa che può esistere anche fuori dall'archivio.</li>
<li><b>Reserved:</b> Admin, Formazione e le persone che abilitano. Per gli altri, nell'app non esiste.</li>
</ul>
<p>Un livello decide che cosa mostra l'app. I PDF restano su Drive con un link pubblico.</p>
</details>$help_guide$, 270, now(), 'migration 116');

create index if not exists help_pages_guide_key_idx on public.help_pages (guide_key);

commit;

-- ============================================================================
-- Self-test: the SQL Editor shows only this last result. All rows must be true.
-- ============================================================================
select 'backup holds the old pages' as item,
       (select count(*) >= 18 from public._backup_help_pages_20261106) as ok
union all select '27 guides, each in English and Italian',
       (select count(*) = 54 and count(distinct guide_key) = 27 from public.help_pages)
union all select 'every guide has a section and an audience',
       (select count(*) = 0 from public.help_pages where section is null or cardinality(audience) = 0)
union all select 'no old wording left',
       (select count(*) = 0 from public.help_pages where html_content ~ 'Urdu Archive Manager|Promote to archive')
union all select 'Read aloud guide not shown to plain Users yet',
       (select count(*) = 0 from public.help_pages where guide_key = 'read-aloud' and 'user' = any(audience))
union all select 'plain Users can read help_pages (policy unchanged)',
       (select count(*) = 1 from pg_policies where tablename = 'help_pages' and policyname = 'help_pages_select');
